import React, { useState, useEffect } from 'react';
import { toast } from 'react-toastify';

function OrderHistory() {
    const [orders, setOrders] = useState([]);
    const [loading, setLoading] = useState(true);
    const [selectedCode, setSelectedCode] = useState(null);
    const [loadedOrders, setLoadedOrders] = useState(10);
    const [allOrders, setAllOrders] = useState([]);
    const [reviewOrderId, setReviewOrderId] = useState(null);
    const [reviewText, setReviewText] = useState('');
    const [rating, setRating] = useState(0);

    useEffect(() => {
        const fetchOrders = async () => {
            try {
                const token = localStorage.getItem('token');

                const response = await fetch('https://gachashop-backend.onrender.com/order/orders', {
                    headers: {
                        'Authorization': `Bearer ${token}`,
                    },
                });

                if (!response.ok) {
                    throw new Error('Ошибка при получении данных');
                }

                const data = await response.json();
                setAllOrders(data); // Сохраняем все заказы
                setOrders(data.slice(0, 10)); // Первоначально загружаем только 10 заказов
            } catch (error) {
                toast.error('Ошибка при загрузке истории заказов');
                console.error('Ошибка:', error);
            } finally {
                setLoading(false);
            }
        };

        fetchOrders();
    }, []);

    const handleShowCode = (orderCode) => {
        setSelectedCode(orderCode);
    };

    const handleCloseModal = () => {
        setSelectedCode(null);
    };

    const handleLoadMore = () => {
        const newLoadedOrders = loadedOrders + 10; // Загрузить ещё 10 заказов
        setLoadedOrders(newLoadedOrders);
        setOrders(allOrders.slice(0, newLoadedOrders)); // Обновить список заказов с добавлением новых
    };

    const handleRatingChange = (newRating) => {
        setRating(newRating);
    };

    const handleAddReview = async (orderId) => {
        setReviewOrderId(orderId); // Запоминаем ID заказа для отзыва
    };

    const Star = ({ filled }) => (
        <svg
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 24 24"
            fill={filled ? '#000000' : 'none'} // Заливка в зависимости от состояния
            stroke="#000000" // Чёрная обводка
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
            className="w-8 h-8 cursor-pointer"
        >
            <polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2" />
        </svg>
    );

    const handleSubmitReview = async () => {
        if (rating === 0) {
            toast.error('Пожалуйста, выберите оценку.');
            return;
        }

        try {
            const token = localStorage.getItem('token'); // JWT из localStorage или другого хранилища

            const response = await fetch('https://gachashop-backend.onrender.com/user-review/create', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${token}`,
                },
                body: JSON.stringify({
                    review: rating,
                    text: reviewText,
                    order_id: reviewOrderId,
                }),
            });

            if (!response.ok) {
                throw new Error('Ошибка при добавлении отзыва');
            }

            const data = await response.json();
            if (data.status === 'success') {
                toast.success('Отзыв добавлен успешно');

                // Обновляем список заказов, убирая кнопку "Добавить отзыв" у этого заказа
                setAllOrders((prevOrders) =>
                    prevOrders.map((order) =>
                        order.id === reviewOrderId ? { ...order, has_review: false } : order
                    )
                );

                setOrders((prevOrders) =>
                    prevOrders.map((order) =>
                        order.id === reviewOrderId ? { ...order, has_review: false } : order
                    )
                );

                setReviewOrderId(null);
                setReviewText('');
                setRating(0);
            } else {
                toast.error('Ошибка при добавлении отзыва');
            }
        } catch (error) {
            toast.error('Ошибка при добавлении отзыва');
            console.error('Ошибка:', error);
        }
    };

    if (loading) {
        return <div className="text-center py-10">Загрузка...</div>;
    }

    return (
        <div className="flex flex-col items-center px-4">
            <h2 className="pt-4 text-center font-bold text-2xl lg:text-3xl mb-6 lg:mb-10">История заказов</h2>

            {orders.length === 0 ? (
                <div className='flex justify-center lg:justify-normal lg:items-start w-full'>
                    <p className="text-gray-500 text-center">Заказы отсутствуют.</p>
                </div>

            ) : (
                <div className="w-full grid grid-cols-1 lg:grid-cols-2 gap-4">
                    {orders.map((order) => (
                        <div
                            key={order.id}
                            className="bg-[#976bd6b2] text-white text-left rounded-xl p-4 shadow-md flex flex-col justify-between"
                        >
                            <div>
                                <p><strong>ID:</strong> {order.id}</p>
                                <p><strong>Название:</strong> {order.order_name}</p>
                                <p><strong>Дата:</strong> {new Date(order.order_date).toLocaleString('ru-RU', {
                                    day: '2-digit',
                                    month: '2-digit',
                                    year: 'numeric',
                                    hour: '2-digit',
                                    minute: '2-digit',
                                })}
                                </p>
                                <p><strong>Цена:</strong> {order.order_price} ₽</p>
                                <p><strong>Статус:</strong> {order.order_status}</p>
                            </div>
                            {/* Добавляем кнопку для отзыва, если его нет */}
                            {order.has_review && (
                                <button
                                    onClick={() => handleAddReview(order.id)}
                                    className="mt-4 border-2 border-[#9f78d6] bg-transparent text-white p-2 rounded-xl hover:text-black hover:bg-[#9f78d6] ease-in-out duration-200"
                                >
                                    Добавить отзыв
                                </button>
                            )}
                            <button
                                onClick={() => handleShowCode(order.order_code)}
                                className="mt-4 border-2 border-[#b6d9ee] bg-transparent text-white p-2 rounded-xl hover:text-black hover:bg-[#b6d9ee] ease-in-out duration-200"
                            >
                                Просмотреть код
                            </button>
                        </div>
                    ))}
                </div>
            )}

            {/* Кнопка "Загрузить ещё" */}
            {allOrders.length > loadedOrders && (
                <button
                    onClick={handleLoadMore}
                    className="mt-6 bg-[#96cceb] text-black p-3 rounded-xl hover:bg-[#b6d9ee] transition-all duration-200"
                >
                    Загрузить ещё
                </button>
            )}

            {/* Модальное окно для добавления отзыва */}
            {reviewOrderId && (
                <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50 z-50 px-2 lg:px-0">
                    <div className="bg-[#976BD6] rounded-lg shadow-lg max-w-sm text-center p-4">
                        <h3 className="text-lg text-black font-bold mb-2">Добавить отзыв</h3>

                        {/* Выбор оценки */}
                        <div className="flex space-x-1 mb-[20px]">
                            {[1, 2, 3, 4, 5].map((star) => (
                                <div key={star} onClick={() => handleRatingChange(star)}>
                                    <Star filled={star <= rating} />
                                </div>
                            ))}
                        </div>

                        {/* Текст отзыва */}
                        <textarea
                            value={reviewText}
                            onChange={(e) => setReviewText(e.target.value)}
                            placeholder="Напишите ваш отзыв (необязательно)"
                            className="w-full p-2 rounded-lg mb-4 text-black focus:ring-0 focus:ring-offset-0 border-0"
                        ></textarea>

                        <button
                            onClick={handleSubmitReview}
                            disabled={rating === 0} // Кнопка заблокирована, если рейтинг не выбран
                            className={`bg-[#8445dd] text-white px-4 py-2 rounded border border-[#8445dd] hover:bg-white hover:text-[#976BD6] ease-in-out duration-150 ${rating === 0 ? 'cursor-not-allowed opacity-50' : ''}`}
                        >
                            Отправить отзыв
                        </button>
                        <button
                            onClick={() => setReviewOrderId(null)}
                            className="ml-4 bg-gray-300 border border-gray-300 text-black px-4 py-2 rounded hover:bg-white hover:text-gray-600 ease-in-out duration-150"
                        >
                            Закрыть
                        </button>
                    </div>
                </div>
            )}

            {/* Модальное окно для отображения кода */}
            {selectedCode && (
                <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50 z-50">
                    <div className="bg-[#976BD6] rounded-lg shadow-lg max-w-sm text-center p-4">
                        <h3 className="text-lg text-black font-bold mb-2">Код заказа</h3>
                        <p className="mb-4 text-black">{selectedCode}</p>
                        <button
                            onClick={() => navigator.clipboard.writeText(selectedCode)}
                            className="bg-[#8445dd] text-white px-4 py-2 rounded border border-[#8445dd] hover:bg-white hover:text-[#976BD6] ease-in-out duration-150"
                        >
                            Скопировать код
                        </button>
                        <button
                            onClick={handleCloseModal}
                            className="ml-4 bg-gray-300 border border-gray-300 text-black px-4 py-2 rounded hover:bg-white hover:text-gray-600 ease-in-out duration-150"
                        >
                            Закрыть
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
}

export default OrderHistory;
