import { useEffect, useState } from 'react';
import { useNavigate, NavLink, Outlet } from 'react-router-dom';
import Header from '../components/Header';
import Footer from '../components/Footer';

// Функция для получения данных пользователя
async function fetchUserData() {
    const token = localStorage.getItem('token');

    if (!token) {
        console.warn('Токен не найден в localStorage');
        return null;
    }

    try {
        const response = await fetch('https://gachashop-backend.onrender.com/user/get-user-data', {
            method: 'GET',
            headers: {
                'Authorization': `Bearer ${token}`,
                'Content-Type': 'application/json',
            },
        });

        const data = await response.json();

        if (!response.ok) {
            console.error('Ошибка получения данных пользователя:', data.message || response.statusText);
            return null;
        }

        return data;
    } catch (error) {
        console.error('Ошибка при получении данных пользователя:', error);
        return null;
    }
}

function AdminPanel() {
    const [loading, setLoading] = useState(true);
    const [isAdmin, setIsAdmin] = useState(false);
    const navigate = useNavigate();

    useEffect(() => {
        const checkAdminStatus = async () => {
            const userData = await fetchUserData();
            if (userData && userData.is_admin === 1) {
                setIsAdmin(true); // Пользователь является администратором
            } else {
                navigate('/'); // Если не админ, перенаправляем на главную
            }
            setLoading(false);
        };

        checkAdminStatus();
    }, [navigate]);

    if (loading) {
        return <div>Loading...</div>;
    }

    if (!isAdmin) {
        return null; // Возвращаем пустой компонент, если не админ
    }

    return (
        <div className="bg-[#000000] font-seravek min-h-screen flex flex-col">
            <Header />
            <div className="flex flex-col flex-grow text-white">
                <div className="container flex flex-col lg:flex-row flex-grow mx-auto mt-10 mb-5 gap-4">
                    <div className="bg-[#1e1e1e] rounded-xl p-2 w-full lg:w-64 lg:h-32">
                        <nav className="flex flex-row lg:flex-col justify-around lg:space-y-2 space-x-2 lg:space-x-0 text-center lg:text-left">
                            <NavLink
                                to="products"
                                className={({ isActive }) =>
                                    isActive
                                        ? 'block py-1 px-2 text-black bg-menu-purple rounded-lg'
                                        : 'block py-1 px-2 text-white bg-[#3d3d3d] rounded-lg hover:bg-hover-purple ease-in-out duration-100'
                                }
                            >
                                Управление товарами
                            </NavLink>
                            <NavLink
                                to="user-orders"
                                className={({ isActive }) =>
                                    isActive
                                        ? 'block py-1 px-2 text-black bg-menu-purple rounded-lg'
                                        : 'block py-1 px-2 text-white bg-[#3d3d3d] rounded-lg hover:bg-hover-purple ease-in-out duration-100'
                                }
                            >
                                Управление заказами
                            </NavLink>
                            <NavLink
                                to="reviews"
                                className={({ isActive }) =>
                                    isActive
                                        ? 'block py-1 px-2 text-black bg-menu-purple rounded-lg'
                                        : 'block py-1 px-2 text-white bg-[#3d3d3d] rounded-lg hover:bg-hover-purple ease-in-out duration-100'
                                }
                            >
                                Управление отзывами
                            </NavLink>
                        </nav>
                    </div>

                    {/* Основной контент */}
                    <main className="flex-grow w-full px-2 lg:px-0">
                        <Outlet />
                    </main>
                </div>
            </div>
            <Footer />
        </div>
    );
}

export default AdminPanel;
