import Header from "../components/Header";
import Footer from "../components/Footer";
import React, { useState } from 'react';
import { Link } from "react-router-dom";
import { useForm } from "react-hook-form";
import { FaEye, FaEyeSlash } from "react-icons/fa";
import { toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

import user from "../components/images/Register_and_Auth/user.png";
import pass from "../components/images/Register_and_Auth/padlock.png";
import question from "../components/images/Register_and_Auth/question.png";
import answer from "../components/images/Register_and_Auth/conversation.png";
import back from "../components/images/Register_and_Auth/back-button.png";

function ResetPassword({ onBackToLogin }) {
    const [step, setStep] = useState(1);
    const [passwordEye, setPasswordEye] = useState(true); // Для показа/скрытия пароля
    const [selectedQuestion, setSelectedQuestion] = useState('');
    const [nickname, setNickname] = useState('');

    const { register, handleSubmit, formState: { errors }, watch } = useForm({
        mode: 'onChange'
    });

    const handleSelectChange = (event) => {
        setSelectedQuestion(event.target.value);
    };

    const handlePasswordClick = () => {
        setPasswordEye(!passwordEye);
    };

    const secretQuestions = [
        'Какой ваш любимый цвет?',
        'Какое ваше любимое блюдо?',
        'Какое ваше любимое животное?',
    ];

    // Функция для обработки первого шага (проверка никнейма и ответа на секретный вопрос)
    const handleStep1Submit = async (data) => {
        setNickname(data.nickname);

        try {
            const response = await fetch('https://gachashop-backend.onrender.com/user/check-secret-question', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    nickname: data.nickname,
                    answer: data.answerSecretQuestion
                })
            });

            const responseData = await response.json();

            if (response.ok && responseData.status === 'success') {
                toast.success('Ответ на секретный вопрос верен');
                setStep(2);  // Переходим к шагу изменения пароля
            } else {
                toast.error('Неправильный ответ на секретный вопрос');
            }
        } catch (error) {
            toast.error('Ошибка проверки вопроса');
        }
    };


    // Функция для обработки второго шага (сброс пароля)
    const handleStep2Submit = async (data) => {
        try {
            const response = await fetch('https://gachashop-backend.onrender.com/user/reset-password', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    nickname: nickname,  // Никнейм, сохранённый из первого шага
                    newPassword: data.password  // Новый пароль
                })
            });

            const responseData = await response.json();

            if (response.ok && responseData.status === 'success') {
                toast.success('Пароль успешно изменён');
                setStep(3);  // Переход на этап успеха
            } else if (responseData.message === 'Новый пароль не должен совпадать с предыдущим') {
                toast.error('Ошибка: Новый пароль не должен совпадать с предыдущим');
            } else {
                toast.error('Ошибка при сбросе пароля');
            }
        } catch (error) {
            toast.error('Ошибка сброса пароля');
        }
    };

    // Валидация пароля (совпадение с подтверждением)
    const validatePasswordMatch = (value) => {
        return value === watch('password') || 'Пароли должны совпадать';
    };

    return (
        <div className="bg-[#000000] font-seravek min-h-screen flex flex-col">

            <Header />

            {/* Кнопка назад */}
            <div className="container mx-auto px-6 md:px-11 mt-[30px] xl:mb-10">
                <Link to="/auth?form=login" className="flex flex-row justify-start items-center space-x-1 md:space-x-3">
                    <img src={back} alt="Стрелка назад" className="w-3 md:w-5 lg:w-5 xl:w-6" />
                    <span className="text-sm md:text-base xl:text-lg text-[#FFFFFF]">Вернуться ко входу</span>
                </Link>
            </div>

            <div className="flex flex-col justify-center flex-grow">
                <div className="container px-4 flex items-center flex-col mx-auto">

                    {/* Форма */}
                    <div className="w-full xl:w-[1118px] xl:h-[400px] flex border rounded-lg font-seravek bg-[#000000]">
                        <form onSubmit={handleSubmit(step === 1 ? handleStep1Submit : handleStep2Submit)}
                            className="w-full flex flex-col justify-center items-center gap-5">
                            {step === 1 && (
                                <>
                                    <div><p className="text-[#FFFFFF] text-xl xl:text-3xl font-bold pt-4 xl:pt-0">Сброс пароля (этап 1 из 2)</p></div>
                                    <div className="w-full space-y-2 lg:space-y-[10px] px-4">
                                        {/* Никнейм */}
                                        <div className="relative">
                                            <input
                                                type="text"
                                                className={`w-full xl:h-[56px] rounded-lg bg-[#D9D9D9] placeholder:text-base lg:placeholder:text-lg pl-[50px] border-0 active:ring-0 active:ring-offset-0 ${errors.nickname &&
                                                    "focus:border-[#ff7777] focus:ring-[#ff7777] border-[#ff7777]"}`}
                                                placeholder="Введите никнейм*"
                                                {...register("nickname", {
                                                    required: 'Поле обязательно к заполнению',
                                                    minLength: {
                                                        value: 4,
                                                        message: 'Минимальное количество символов 4'
                                                    }
                                                })}
                                            />
                                            <span className="absolute top-5 xl:top-7 left-3 transform -translate-y-1/2">
                                                <img src={user} alt="user" className="w-7 xl:w-[31px]" />
                                            </span>
                                            {errors.nickname && <span className="text-[#ff7777] text-base">{errors.nickname.message}</span>}
                                        </div>

                                        {/* Выбор секретного вопроса */}
                                        <div className="relative">
                                            <select
                                                className={`w-full xl:h-[56px] rounded-lg bg-[#D9D9D9] pl-[50px] text-base xl:text-lg text-[#000000] border-0 focus:ring-0 focus:ring-offset-0 focus:cursor-pointer 
                                                    ${errors.secretQuestion && "focus:border-[#ff7777] focus:ring-[#ff7777] border-[#ff7777]"}
                                                    ${selectedQuestion ? "text-opacity-100" : "text-opacity-50"}  transition-opacity duration-300`}
                                                {...register("secretQuestion", {
                                                    required: 'Не выбран секретный вопрос'
                                                })}

                                                value={selectedQuestion}
                                                onChange={handleSelectChange}>

                                                <option className="hidden" disabled value="">Выберите вопрос*</option>
                                                {secretQuestions.map((question, index) => (
                                                    <option key={index} value={question}>
                                                        {question}
                                                    </option>
                                                ))}

                                            </select>
                                            <span className="absolute top-5 xl:top-7 left-3 transform -translate-y-1/2">
                                                <img src={question} alt="question" className="w-7 xl:w-[31px]" />
                                            </span>
                                            {errors.secretQuestion && <span className="text-[#ff7777] text-[14px]">{errors.secretQuestion.message}</span>}
                                        </div>

                                        {/* Ответ на секретный вопрос */}
                                        <div className="relative">
                                            <input
                                                type="text"
                                                className={`w-full xl:h-[56px] rounded-lg bg-[#D9D9D9] xl:placeholder:text-lg pl-[50px] ${errors.confirmPassword &&
                                                    "focus:border-[#ff7777] focus:ring-[#ff7777] border-[#ff7777]"}`}
                                                placeholder="Ответ на секретный вопрос*"
                                                {...register("answerSecretQuestion", {
                                                    required: 'Не дан ответ на секретный вопрос',
                                                })}
                                            />
                                            <span className="absolute top-5 xl:top-7 left-3 transform -translate-y-1/2">
                                                <img src={answer} alt="answer" className="w-7 xl:w-[31px]" />
                                            </span>
                                            {errors.answerSecretQuestion && <span className="text-[#ff7777] text-[14px]">{errors.answerSecretQuestion.message}</span>}
                                        </div>
                                    </div>

                                    <div className="pb-4 xl:pb-0">
                                        <input type="submit" value="Продолжить"
                                            className="px-6 xl:px-17 border border-[#976BD6] rounded-full text-[#976BD6] text-lg xl:text-2xl flex justify-center items-center hover:text-[#000000] hover:bg-[#976BD6] hover:cursor-pointer ease-in-out duration-200" />
                                    </div>
                                </>
                            )}

                            {step === 2 && (
                                <>
                                    <div><p className="text-[#FFFFFF] text-xl xl:text-3xl font-bold pt-4 xl:pt-0">Сброс пароля (этап 2 из 2)</p></div>
                                    <div className="w-full space-y-2 lg:space-y-[10px] px-4">
                                        {/* Новый пароль */}
                                        <div className="relative">
                                            <input
                                                type={(passwordEye === false) ? "text" : "password"}
                                                className={`w-full xl:h-[56px] rounded-lg bg-[#D9D9D9] xl:placeholder:text-lg pl-[50px] ${errors.password &&
                                                    "focus:border-[#ff7777] focus:ring-[#ff7777] border-[#ff7777]"}`}
                                                placeholder="Введите новый пароль*"
                                                {...register("password", {
                                                    required: 'Поле пароля обязательно к заполнению',
                                                    pattern: {
                                                        value: /^(?=.*?[A-Z])(?=.*?[a-z])(?=.*?[0-9])(?=.*?[.#?!@$%^&*-]).{8,}$/,
                                                        message: 'Пароль должен иметь хотя бы одну латинскую заглавную и прописную букву, одну цифру и один специальный знак из набора: .#?!@$%^&*-'
                                                    },

                                                    minLength: {
                                                        value: 8,
                                                        message: 'Минимальное количество символов 8'
                                                    }
                                                })}
                                            />
                                            <span className="absolute top-5 xl:top-7 left-3 transform -translate-y-1/2">
                                                <img src={pass} alt="password" className="w-7 xl:w-[31px]" />
                                            </span>
                                            {errors.password && <span className="text-[#ff7777] text-[14px]">{errors.password.message}</span>}

                                            {/* Глазики */}
                                            <div className="absolute top-2 xl:top-4 text-2xl right-2">
                                                {
                                                    (passwordEye === false) ? <FaEye onClick={handlePasswordClick} className="text-[#976BD6]" /> :
                                                        <FaEyeSlash onClick={handlePasswordClick} className="text-[#976BD6]" />
                                                }
                                            </div>
                                        </div>

                                        {/* Подтверждение пароля */}
                                        <div className="relative">
                                            <input type="password"
                                                className={`w-full xl:h-[56px] rounded-lg bg-[#D9D9D9] xl:placeholder:text-lg pl-[50px] 
                                                    ${errors.confirmPassword &&
                                                    "focus:border-[#ff7777] focus:ring-[#ff7777] border-[#ff7777]"}`}
                                                placeholder="Повторите пароль*"
                                                {...register("confirmPassword",
                                                    {
                                                        required: 'Подтвердите пароль',
                                                        validate: validatePasswordMatch
                                                    })} />
                                            {errors.confirmPassword && <span className="text-[#ff7777] text-[14px]">{errors.confirmPassword.message}</span>}

                                            <span className="absolute top-5 xl:top-7 left-3 transform -translate-y-1/2">
                                                <img src={pass} alt="password" className="w-7 xl:w-[31px]" />
                                            </span>
                                        </div>
                                    </div>

                                    <div className="pb-4 xl:pb-0">
                                        <input type="submit" value="Сбросить пароль"
                                            className="px-6 xl:px-17 border border-[#976BD6] rounded-full text-[#976BD6] text-lg xl:text-2xl flex justify-center items-center hover:text-[#000000] hover:bg-[#976BD6] hover:cursor-pointer ease-in-out duration-200" />
                                    </div>
                                </>
                            )}

                            {step === 3 && (
                                <>
                                    <div>
                                        <p className="text-[#FFFFFF] text-xl pt-4 xl:pt-0 xl:text-3xl font-bold">Пароль успешно сброшен!</p>
                                    </div>

                                    <button onClick={() => window.location.href = '/auth?form=login'} className="mb-4 xl:mb-0 px-6 xl:px-17 border border-[#976BD6] rounded-full text-[#976BD6] text-lg xl:text-2xl flex justify-center items-center hover:text-[#000000] hover:bg-[#976BD6] hover:cursor-pointer ease-in-out duration-200">Перейти ко входу</button>
                                </>
                            )}
                        </form>
                    </div>
                </div>
            </div>
            <Footer />
        </div>




    );
}

export default ResetPassword;