import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import RouteWatcher from '../components/RouteWatcher'
import { UserProvider } from "../components/Context";
import { ToastContainer } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import { ThemeProvider } from '@mui/material/styles';
import theme from './theme'; // Импортируй только что созданную тему

import Home from "../pages/Home";
import GameChoose from "../pages/GameChoose";
import Catalog from "../pages/Catalog";
import Reviews from "../pages/Reviews";
import Faq from "../pages/Faq";
import Support from "../pages/Support";
import Authentication from "../pages/Authentication";
import ResetPassword from "../pages/ResetPassword";
import ProductPage from "../pages/ProductPage";
import AccountSettings from "../pages/AccountSettings";
import CheckoutPage from "../pages/CheckoutPage";
import Success from '../pages/Success';
import UserReview from '../pages/UserReview';
import Category from '../pages/Category';
import PersonalInfoSection from './PersonalInfoSection';
import OrderHistory from './OrderHistory';
import PaymentMethods from './PaymentMethods';
import ChangePassword from './ChangePassword';
import AdminPanel from '../pages/AdminPanel';
import ProductManagement from './ProductManagement';
import UserOrders from './UserOrders';
import ReviewManagement from './ReviewManagement';

function Links() {

    return (
        <HashRouter future={{
            v7_startTransition: true,
            v7_relativeSplatPath: true,
        }}>
            <RouteWatcher />
            <ThemeProvider theme={theme}>
                <UserProvider>
                    <ToastContainer position="bottom-right" autoClose={5000} hideProgressBar={false} />
                    <Routes>
                        <Route path="/" element={<Home />} />
                        <Route path="/gamechoose" element={<GameChoose />} />
                        <Route path="/catalog" element={<Catalog />} />
                        <Route path="/product/:productId" element={<ProductPage />} />
                        <Route path="/checkout" element={<CheckoutPage />} />
                        <Route path='/success' element={<Success />} />
                        <Route path='/user-review' element={<UserReview />} />
                        <Route path="/reviews" element={<Reviews />} />
                        <Route path="/faq" element={<Faq />} />
                        <Route path="/support" element={<Support />} />
                        <Route path="/category" element={<Category />} />
                        <Route path="/auth" element={<Authentication />} />
                        <Route path="/reset" element={<ResetPassword />} />
                        <Route path="/settings" element={<AccountSettings />}>
                            <Route path="/settings/personal-info" element={<PersonalInfoSection />} />
                            <Route path="order-history" element={<OrderHistory />} />
                            <Route path="payment-methods" element={<PaymentMethods />} />
                            <Route path="change-password" element={<ChangePassword />} />
                        </Route>
                        <Route path="/admin" element={<AdminPanel />}>
                            <Route path="products" element={<ProductManagement />} />
                            <Route path="user-orders" element={<UserOrders />} />
                            <Route path="reviews" element={<ReviewManagement />} />
                        </Route>
                        <Route path="*" element={<Navigate to="/" />} />
                    </Routes>
                </UserProvider>
            </ThemeProvider>
        </HashRouter>
    );
}


export default Links;