import { useState, useEffect } from 'react';
import { useUserContext } from "../components/Context";
import { toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

const PersonalInfoSection = () => {
    const { user, updateUser } = useUserContext();
    const [nickname, setNickname] = useState(user ? user.nickname : '');
    const [avatarFile, setAvatarFile] = useState(null);
    const [isSaving, setIsSaving] = useState(false);
    const [cashbackPoints, setCashbackPoints] = useState(0);

    useEffect(() => {
        if (user?.nickname) {
            setNickname(user.nickname);
        }
    }, [user]);

    // Обработчик выбора аватара
    const handleAvatarChange = (e) => {
        const file = e.target.files[0];
        if (file) {
            setAvatarFile(file); // Устанавливаем файл
        }
    };

    useEffect(() => {
        if (user) {
            const fetchUserCashback = async () => {
                try {
                    const token = localStorage.getItem('token');

                    const response = await fetch(`https://gachashop-backend.onrender.com/user/get-user-cashback`, {
                        method: 'GET',
                        headers: {
                            'Content-Type': 'application/json',
                            'Authorization': `Bearer ${token}`,
                        },
                    });
                    if (response.ok) {
                        const data = await response.json();
                        setCashbackPoints(data.user_cashback); // Получаем кэшбек с сервера и сохраняем в состояние
                    } else {
                        console.error("Ошибка при получении кэшбека пользователя");
                    }
                } catch (error) {
                    console.error("Ошибка при запросе кэшбека пользователя:", error);
                }
            };

            fetchUserCashback();
        }
    }, [user]);

    const handleSaveChanges = async () => {
        setIsSaving(true);

        let hasChanges = false;
        const updatedFields = {};

        // 1. Проверка аватара
        if (avatarFile) {
            try {
                const formData = new FormData();
                formData.append("file", avatarFile);
                formData.append("upload_preset", "avatars_default");
                formData.append("folder", `avatars/user_${user.id}`);

                const publicId = `avatar_${user.id}_${Date.now()}`;
                formData.append("public_id", publicId);

                const uploadResponse = await fetch("https://api.cloudinary.com/v1_1/dhicjidvw/image/upload", {
                    method: "POST",
                    body: formData,
                });

                const uploadData = await uploadResponse.json();

                if (uploadData.secure_url) {
                    updatedFields.avatar_url = uploadData.secure_url;
                    hasChanges = true;
                } else {
                    throw new Error("Ошибка при загрузке на Cloudinary");
                }
            } catch (error) {
                console.error("Ошибка при загрузке изображения:", error);
                toast.error("Произошла ошибка при загрузке изображения");
                setIsSaving(false);
                return;
            }
        }

        // 2. Проверка никнейма
        if (nickname.trim() !== "" && nickname !== user.nickname) {
            updatedFields.nickname = nickname;
            hasChanges = true;
        } else if (nickname.trim() === "") {
            setNickname(user.nickname); // Сбросим обратно
            toast.info("Никнейм не может быть пустым. Восстановлено предыдущее значение.");
        }

        // 3. Проверка на отсутствие изменений
        if (!hasChanges) {
            toast.info("Нет изменений для сохранения.");
            setIsSaving(false);
            return;
        }

        // 4. Отправка запроса
        try {
            const token = localStorage.getItem('token');

            const response = await fetch(`https://gachashop-backend.onrender.com/user/update`, {
                method: "POST",
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${token}`,
                },
                body: JSON.stringify(updatedFields),
            });

            const data = await response.json();
            if (data.success) {
                toast.success("Данные успешно обновлены");
                updateUser({
                    ...user,
                    ...updatedFields,
                });
            } else {
                toast.error("Ошибка при сохранении данных");
            }
        } catch (error) {
            console.error("Ошибка при отправке данных на сервер:", error);
            toast.error("Произошла ошибка при сохранении данных");
        }

        setIsSaving(false);
    }

    return (
        <>
            <p className='pt-4 text-center lg:text-start font-bold text-xl lg:text-3xl mb-6 lg:mb-10'>Персональная информация</p>

            {user ?
                <div className='flex flex-col-reverse justify-center lg:flex-row flex-grow gap-4 lg:gap-0'>

                    {/* Кнопка (скрыта при немобилках) */}
                    <div className='flex lg:hidden'>
                        <button
                            onClick={handleSaveChanges}
                            disabled={isSaving}
                            className="border lg:border-2 rounded-full px-4 py-1 text-lg lg:text-xl text-[#976BD6] border-[#976BD6] hover:bg-[#976BD6] hover:text-black ease-in-out duration-150"
                        >
                            {isSaving ? 'Сохранение...' : 'Сохранить изменения'}
                        </button>
                    </div>

                    {/* Аватар */}
                    <div className='flex flex-col lg:pr-4'>
                        <label className='text-md lg:text-xl'>Аватар</label>
                        <div className='hover:cursor-pointer'>
                            <img
                                src={user.avatar_url}
                                alt="Аватар"
                                className='rounded-lg w-24 lg:w-36'
                                onClick={() => document.getElementById('avatar-input').click()}
                            />
                            <input
                                type="file"
                                id="avatar-input"
                                style={{ display: 'none' }}
                                accept="image/*"
                                onChange={handleAvatarChange}
                            />
                        </div>

                    </div>

                    {/* Остальные поля и кнопка */}
                    <div className='flex flex-col space-y-2 lg:space-y-5'>
                        <div className='flex flex-col'>
                            <label className='text-md lg:text-xl'>Никнейм (можно изменить)</label>
                            <input
                                type="text"
                                value={nickname}
                                className='w-full lg:w-96 rounded-xl text-black focus:ring-0 focus:ring-offset-0 border-0'
                                onChange={(e) => setNickname(e.target.value)}
                                placeholder="Введите новый никнейм"
                            />
                        </div>

                        <div className='text-md lg:text-xl'>
                            <label>Ваш кэшбек составляет: </label>
                            <span>{cashbackPoints} баллов</span>
                        </div>

                        <div className='hidden lg:block'>
                            <button
                                onClick={handleSaveChanges}
                                disabled={isSaving}
                                className="border lg:border-2 rounded-full px-4 text-md lg:text-xl text-[#976BD6] border-[#976BD6] hover:bg-[#976BD6] hover:text-black ease-in-out duration-150"
                            >
                                {isSaving ? 'Сохранение...' : 'Сохранить изменения'}
                            </button>
                        </div>

                    </div>

                </div>
                :
                <p>Загрузка...</p>}
        </>
    );
};

export default PersonalInfoSection;
