import React, { useState, useEffect } from 'react';
import { toast } from 'react-toastify';
import { useUserContext } from '../components/Context';
import confirmationDialog from '../components/ConfirmationDialog'; // Модальное окно для подтверждения удаления

function PaymentMethods() {
    const [cards, setCards] = useState([]); // Сохраняем список карт
    const { user } = useUserContext(); // Получаем пользователя

    useEffect(() => {
        // Получаем список карт при загрузке компонента
        const fetchCards = async () => {
            try {
                const response = await fetch(`https://gachashop-backend.onrender.com/card/cards`, {
                    method: 'GET',
                    headers: {
                        'Authorization': `Bearer ${localStorage.getItem('token')}`,
                    },
                });
                if (response.ok) {
                    const data = await response.json();

                    if (data.status === 'error') {
                        setCards([]);
                    } else {
                        setCards(data.cards);
                    }
                } else {
                    throw new Error('Ошибка при получении списка карт');
                }
            } catch (error) {
                console.error('Ошибка:', error);
                toast.error('Ошибка при получении карт');
            }
        };


        if (user) {
            fetchCards(); // Запрашиваем карты только если есть пользователь
        }
    }, [user]);

    // Функция для удаления карты
    const handleDelete = async (cardId) => {
        const confirmed = await confirmationDialog('Подтвердить удаление карты?', 'Вы уверены, что хотите удалить эту карту?');
        if (confirmed) {
            try {
                const response = await fetch(`https://gachashop-backend.onrender.com/card/delete/${cardId}`, {
                    method: 'DELETE',
                    credentials: "include"
                });
                if (response.ok) {
                    toast.success('Карта удалена');
                    setCards(cards.filter(card => card.id !== cardId)); // Удаляем карту из состояния
                } else {
                    throw new Error('Ошибка при удалении карты');
                }
            } catch (error) {
                console.error('Ошибка:', error);
                toast.error('Ошибка при удалении карты');
            }
        }
    };

    return (
        <div>
            <h2 className="pt-4 text-center font-bold text-2xl lg:text-3xl mb-6 lg:mb-10">Прикреплённые карты</h2>
            {cards && cards.length === 0 ? (
                <p className="text-gray-400 text-center lg:text-left">У вас нет сохранённых карт</p>
            ) : (
                <ul className="space-y-4">
                    {cards && cards.map(card => (
                        <li key={card.id} className="flex justify-between items-center py-2 px-4 border-2 rounded-xl">
                            <div className="text-white text-lg">
                                <p>{card.card_number}</p>
                            </div>
                            <button
                                onClick={() => handleDelete(card.id)}
                                className="text-red-500 hover:underline"
                            >
                                Удалить
                            </button>
                        </li>
                    ))}
                </ul>
            )}

        </div>
    );
}

export default PaymentMethods;
