import React, { useState } from 'react';
import { useForm, Controller } from "react-hook-form";
import { Listbox } from '@headlessui/react';
import { FaChevronDown, FaEye, FaEyeSlash } from "react-icons/fa";

import user from "../components/images/Register_and_Auth/user.png";
import pass from "../components/images/Register_and_Auth/padlock.png";
import question from "../components/images/Register_and_Auth/question.png";
import answer from "../components/images/Register_and_Auth/conversation.png";

function Register({ onSwitchToLogin, onSubmit }) {
  const { register, handleSubmit, watch, control, formState: { errors } } = useForm({
    mode: 'onChange'
  });

  const [passwordEye, setPasswordEye] = useState(true);
  const handlePasswordClick = () => setPasswordEye(!passwordEye);

  const [confirmPasswordEye, setConfirmPasswordEye] = useState(true);
  const handleConfirmPasswordClick = () => setConfirmPasswordEye(!confirmPasswordEye);

  const password = watch('password');

  const questions = [
    'Ваш любимый цвет?',
    'Ваше любимое блюдо?',
    'Ваше любимое животное?',
  ];

  return (
    <div className="w-[300px] md:w-[350px] lg:w-[920px] xl:w-[1118px] h-[602px] flex flex-col-reverse gap-4 lg:flex-row justify-between border rounded-lg font-seravek bg-[#000000]" id="register-component">

      {/* Левая часть */}
      <div className="lg:h-full py-2 bg-[#976BD6] flex flex-col justify-center items-center gap-2 lg:gap-4 xl:gap-6">
        <div className="flex flex-col space-y-2 text-center">
          <p className="text-lg lg:text-2xl xl:text-[35px] font-bold">Добро пожаловать!</p>
          <p className="text-sm lg:text-lg xl:text-[20px]">
            Регистрация откроет вам доступ к системе кэшбека и возможности создавать заказы.
            <br />
            Создайте свой уникальный опыт покупок!
          </p>
        </div>

        <button
          className="px-16 lg:px-28 py-1 border border-[#000000] rounded-full text-[#000000] text-sm lg:text-xl xl:text-2xl flex justify-center items-center hover:text-[#976BD6] hover:bg-[#000000] ease-in-out duration-200"
          onClick={onSwitchToLogin}>
          Войти
        </button>

      </div>

      {/* Правая часть */}
      <div className='flex flex-col justify-center items-center w-full h-full'>
        <form
          onSubmit={handleSubmit(onSubmit)}
          className="flex flex-col justify-center items-center w-full lg:pt-0 gap-2 lg:gap-4">

          <div>
            <p className="text-[#FFFFFF] text-xl lg:text-3xl xl:text-4xl font-bold">Регистрация</p>
          </div>

          <div className="w-full px-6 lg:px-14 xl:px-20 space-y-2">

            {/* Никнейм */}
            <div className="relative">
              <input
                autoComplete="off"
                type="text"
                className={`w-full h-10 lg:h-[56px] rounded-lg bg-[#D9D9D9] pl-[50px]
    focus:outline-none focus:ring-2 focus:ring-[#976BD6] focus:border-[#976BD6] ${errors.nickname && "focus:border-[#ff7777] focus:ring-[#ff7777] border-[#ff7777]"}`}
                placeholder="Придумайте логин*"
                {...register("nickname", {
                  required: 'Логин обязателен к заполнению',
                  minLength: {
                    value: 4,
                    message: 'Минимальное количество символов 4'
                  }
                })}
              />
              <span className="absolute top-5 lg:top-7 left-3 transform -translate-y-1/2">
                <img src={user} alt="user" className="w-6 lg:w-[31px]" />
              </span>
              {errors.nickname && <span className="text-[#ff7777] text-sm">{errors.nickname.message}</span>}
            </div>

            {/* Пароль */}
            <div className="relative">
              <input
                autoComplete='new-password'
                type={(passwordEye === false) ? "text" : "password"}
                className={`w-full h-10 lg:h-[56px] rounded-lg bg-[#D9D9D9] pl-[50px]
    focus:outline-none focus:ring-2 focus:ring-[#976BD6] focus:border-[#976BD6] ${errors.password && "focus:border-[#ff7777] focus:ring-[#ff7777] border-[#ff7777]"}`}
                placeholder="Придумайте пароль*"
                {...register("password", {
                  required: 'Пароль обязателен к заполнению',
                  pattern: {
                    value: /^(?=.*?[A-Z])(?=.*?[a-z])(?=.*?[0-9])(?=.*?[.#?!@$%^&*-]).{8,}$/,
                    message: 'Пароль должен иметь хотя бы одну заглавную и прописную букву, одну цифру и один спецсимвол .#?!@$%^&*-'
                  },
                  minLength: {
                    value: 8,
                    message: 'Минимальное количество символов 8'
                  }
                })}
              />
              <span className="absolute top-5 lg:top-7 left-3 transform -translate-y-1/2">
                <img src={pass} alt="password" className="w-6 lg:w-[31px]" />
              </span>
              {errors.password && <span className="text-[#ff7777] text-sm">{errors.password.message}</span>}

              {/* Глазики */}
              <div className="absolute top-3 lg:top-4 text-lg lg:text-2xl right-2">
                {
                  (passwordEye === false) ? <FaEye onClick={handlePasswordClick} className="text-[#976BD6]" /> :
                    <FaEyeSlash onClick={handlePasswordClick} className="text-[#976BD6]" />
                }
              </div>
            </div>

            {/* Подтверждение пароля */}
            <div className="relative">
              <input
                autoComplete="off"
                type={(confirmPasswordEye === false) ? "text" : "password"}
                className={`w-full h-10 lg:h-[56px] rounded-lg bg-[#D9D9D9] pl-[50px]
    focus:outline-none focus:ring-2 focus:ring-[#976BD6] focus:border-[#976BD6] ${errors.confirmPassword && "focus:border-[#ff7777] focus:ring-[#ff7777] border-[#ff7777]"}`}
                placeholder="Повторите пароль*"
                onPaste={(e) => {
                  e.preventDefault();
                  return false;
                }}
                {...register("confirmPassword", {
                  required: 'Повтор пароля обязателен',
                  validate: (value) =>
                    value === password || "Пароли не совпадают",
                })}
              />
              <span className="absolute top-5 lg:top-7 left-3 transform -translate-y-1/2">
                <img src={pass} alt="password" className="w-6 lg:w-[31px]" />
              </span>
              {errors.confirmPassword && <span className="text-[#ff7777] text-sm">{errors.confirmPassword.message}</span>}

              {/* Глазики */}
              <div className="absolute top-3 lg:top-4 text-lg lg:text-2xl right-2">
                {
                  (confirmPasswordEye === false) ? <FaEye onClick={handleConfirmPasswordClick} className="text-[#976BD6]" /> :
                    <FaEyeSlash onClick={handleConfirmPasswordClick} className="text-[#976BD6]" />
                }
              </div>
            </div>

            {/* Секретный вопрос */}
            <div className="relative w-full">
              <Controller
                name="secretQuestion"
                control={control}
                rules={{ required: 'Не выбран секретный вопрос' }}
                render={({ field }) => (
                  <Listbox value={field.value || ''} onChange={field.onChange}>
                    <div className="relative">
                      <Listbox.Button
                        className={`w-full h-10 lg:h-[56px] rounded-lg bg-[#D9D9D9] pl-[50px] pr-10 text-left ${!field.value ? "text-black text-opacity-50" : "text-black"
                          } focus:outline-none focus:ring-2 focus:ring-[#976BD6]`}
                      >
                        {field.value || "Секретный вопрос*"}
                        <span className="absolute inset-y-0 right-0 flex items-center pr-3 pointer-events-none">
                          <FaChevronDown className="text-[#976BD6]" />
                        </span>
                      </Listbox.Button>

                      <Listbox.Options className="absolute z-10 mt-1 max-h-60 w-full overflow-auto rounded-md bg-white py-1 text-sm lg:text-base shadow-lg ring-1 ring-black ring-opacity-5 focus:outline-none">
                        {questions.map((question) => (
                          <Listbox.Option
                            key={question}
                            value={question}
                            className={({ active }) =>
                              `relative cursor-pointer select-none py-2 pl-10 pr-4 ${active ? 'bg-[#976BD6] text-white' : 'text-gray-900'
                              }`
                            }
                          >
                            {({ selected }) => (
                              <span className={`text-sm lg:text-base block truncate ${selected ? 'font-medium' : 'font-normal'}`}>
                                {question}
                              </span>
                            )}
                          </Listbox.Option>
                        ))}
                      </Listbox.Options>
                    </div>
                  </Listbox>
                )}
              />
              <span className="absolute top-5 lg:top-7 left-3 transform -translate-y-1/2">
                <img src={question} alt="question" className="w-6 lg:w-[31px]" />
              </span>
              {errors.secretQuestion && <span className="text-[#ff7777] text-sm">{errors.secretQuestion.message}</span>}
            </div>

            {/* Ответ на секретный вопрос */}
            <div className="relative">
              <input
                autoComplete="off"
                type="text"
                className={`w-full h-10 lg:h-[56px] rounded-lg bg-[#D9D9D9] pl-[50px]
    focus:outline-none focus:ring-2 focus:ring-[#976BD6] focus:border-[#976BD6] ${errors.answerSecretQuestion && "focus:border-[#ff7777] focus:ring-[#ff7777] border-[#ff7777]"}`}
                placeholder="Ответ на вопрос*"
                {...register("answerSecretQuestion", {
                  required: 'Не дан ответ на секретный вопрос',
                })}
              />
              <span className="absolute top-5 lg:top-7 left-3 transform -translate-y-1/2">
                <img src={answer} alt="answer" className="w-6 lg:w-[31px]" />
              </span>
              {errors.answerSecretQuestion && <span className="text-[#ff7777] text-sm">{errors.answerSecretQuestion.message}</span>}
            </div>

          </div>

          {/* Кнопка подтверждения */}
          <div>
            <input
              type="submit"
              value="Зарегистрироваться"
              className="px-4 lg:px-10 py-1 border border-[#976BD6] rounded-full text-[#976BD6] text-sm lg:text-xl xl:text-2xl flex justify-center items-center hover:text-[#000000] hover:bg-[#976BD6] hover:cursor-pointer ease-in-out duration-200"
            />
          </div>
        </form>
      </div>
    </div>
  );
}

export default Register;
