import React, { useEffect, useState } from 'react';
import { Menu, MenuItem, Button } from '@mui/material'; // Используем библиотеку для создания выпадающего меню
import { toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

async function fetchStatuses() {
    const token = localStorage.getItem('token');
    try {
        const response = await fetch('https://gachashop-backend.onrender.com/order/get-statuses', {
            method: 'GET',
            headers: {
                'Authorization': `Bearer ${token}`,
            }
        });

        const data = await response.json();
        return data.statuses;
    } catch (error) {
        console.error('Error fetching statuses:', error);
        return [];
    }
}

async function fetchOrders() {
    const token = localStorage.getItem('token');
    try {
        const response = await fetch('https://gachashop-backend.onrender.com/order/get-user-orders', {
            method: 'GET',
            headers: {
                'Authorization': `Bearer ${token}`,
            }
        });

        const data = await response.json();
        return data;
    } catch (error) {
        console.error('Error fetching orders:', error);
        return [];
    }
}

// Удаление заказа
async function deleteOrder(orderId) {
    const token = localStorage.getItem('token');
    try {
        const response = await fetch(`https://gachashop-backend.onrender.com/order/delete/${orderId}`, {
            method: 'DELETE',
            headers: {
                'Authorization': `Bearer ${token}`,
            },
        });

        const result = await response.json();
        console.log('Delete response:', result);

        if (response.ok && result.status === 'success') {
            return { ok: true };
        } else {
            return { ok: false, message: result.message || 'Ошибка при удалении' };
        }
    } catch (error) {
        console.error('Error deleting order:', error);
        return { ok: false, message: error.message };
    }
}

// Обновление статуса заказа
async function updateOrderStatus(orderId, newStatus) {
    const token = localStorage.getItem('token');
    try {
        const response = await fetch(`https://gachashop-backend.onrender.com/order/update-status/${orderId}`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${token}`,
            },
            body: JSON.stringify({ status: newStatus }),
        });
        return response;
    } catch (error) {
        console.error('Error updating order status:', error);
        return { ok: false };
    }
}

function UserOrders() {
    const [orders, setOrders] = useState([]);
    const [statuses, setStatuses] = useState([]); // Для хранения статусов
    const [anchorEl, setAnchorEl] = useState(null);
    const [statusMenuAnchorEl, setStatusMenuAnchorEl] = useState(null); // Для управления меню статусов
    const [isCodeCopied, setIsCodeCopied] = useState(false); // Новое состояние
    const [filter, setFilter] = useState('all'); // Фильтр по статусу (по умолчанию "Отменённые")
    const [selectedOrderId, setSelectedOrderId] = useState(null);

    useEffect(() => {
        const loadOrders = async () => {
            const fetchedOrders = await fetchOrders();
            setOrders(fetchedOrders);
        };

        const loadStatuses = async () => {
            const fetchedStatuses = await fetchStatuses();
            setStatuses(fetchedStatuses);
        };

        loadOrders();
        loadStatuses();
    }, []);

    // Фильтруем заказы на основе выбранного фильтра
    const filteredOrders = orders.filter(order => {
        if (filter === 'cancelled') {
            return order.order_status_name === 'Отменён';
        }
        return true; // Если фильтр "Все заказы", показываем все заказы
    });

    const handleMenuOpen = (event, orderId) => {
        setAnchorEl(event.currentTarget);
        setSelectedOrderId(orderId); // Сохраняем ID выбранного заказа
    };

    const handleMenuClose = () => {
        setAnchorEl(null);
    };

    const handleDelete = async () => {
        const confirmed = window.confirm('Вы уверены, что хотите удалить этот заказ?');
        if (confirmed) {
            const response = await deleteOrder(selectedOrderId); // Используем сохранённый ID
            if (response.ok) {
                setOrders(orders.filter((order) => order.id !== selectedOrderId));
                toast.success('Заказ успешно удалён');
                handleMenuClose();
            } else {
                toast.error('Ошибка при удалении заказа');
            }
        }
    };

    const handleStatusChange = async (newStatusId) => {
        const response = await updateOrderStatus(selectedOrderId, newStatusId);

        if (response.ok) {
            const updatedOrders = await fetchOrders();
            setOrders(updatedOrders);
            toast.success('Статус заказа успешно обновлён');
            setStatusMenuAnchorEl(null);
        } else {
            toast.error('Ошибка при обновлении статуса заказа');
        }
    };

    const handleStatusMenuOpen = (event) => {
        setStatusMenuAnchorEl(event.currentTarget); // Открываем меню статусов
    };

    const handleStatusMenuClose = () => {
        setStatusMenuAnchorEl(null);
    };

    const handleCopyOrderCode = (orderCode) => {
        navigator.clipboard.writeText(orderCode).then(() => {
            setIsCodeCopied(true); // Устанавливаем состояние для кнопки
            toast.success('Код заказа скопирован');

            setTimeout(() => {
                setIsCodeCopied(false); // Возвращаем стандартную надпись после тайм-аута
            }, 3000); // Через 3 секунды уведомление исчезнет
        }).catch(() => {
            toast.error('Ошибка при копировании кода');
        });
    };

    return (
        <div className="container mx-auto flex flex-col items-center lg:items-start px-4">
            <h1 className="pl-2 text-left font-bold text-2xl lg:text-3xl mb-10">Управление заказами</h1>

            {/* Фильтры */}
            <div className="mb-4">
                <Button
                    variant={filter === 'all' ? 'contained' : 'outlined'}
                    onClick={() => setFilter('all')}
                    sx={{
                        marginRight: 2,
                        backgroundColor: filter === 'all' ? '#9f78d6' : 'transparent',
                        color: filter === 'all' ? 'black' : '#9f78d6',
                        borderColor: '#9f78d6'
                    }}
                >
                    Все заказы
                </Button>
                <Button
                    variant={filter === 'cancelled' ? 'contained' : 'outlined'}
                    onClick={() => setFilter('cancelled')}
                    sx={{
                        backgroundColor: filter === 'cancelled' ? '#9f78d6' : 'transparent',
                        color: filter === 'cancelled' ? 'black' : '#9f78d6',
                        borderColor: '#9f78d6',
                    }}
                >
                    Отменённые
                </Button>
            </div>


            <div className="w-full xl:w-auto grid grid-cols-1 lg:grid-cols-2 gap-4">
                {filteredOrders.map((order) => (
                    <div key={order.id} className="bg-[#976bd6b2] text-white rounded-xl p-4 shadow-md flex flex-col md:items-center lg:items-start">
                        <p><strong>ID:</strong> {order.id}</p>
                        <p><strong>Имя:</strong> {order.order_name}</p>
                        <p><strong>Дата:</strong> {new Date(order.order_date).toLocaleString('ru-RU', {
                            day: '2-digit',
                            month: '2-digit',
                            year: 'numeric',
                            hour: '2-digit',
                            minute: '2-digit',
                        })}</p>
                        <p><strong>Цена:</strong> {order.order_price} ₽</p>
                        <p><strong>ID пользователя:</strong> {order.user_id}</p>
                        <p><strong>Статус:</strong> {order.order_status_name}</p>

                        <div className="mt-2 flex flex-wrap gap-2 w-full justify-center lg:justify-start">
                            <Button
                                onClick={(e) => handleMenuOpen(e, order.id)}
                                sx={{
                                    width: {
                                        xs: '100%',
                                        md: 200,
                                        lg: '100%'
                                    },
                                    mt: 2,
                                    backgroundColor: '#96cceb',
                                    color: '#000000',
                                    fontWeight: 'bold',
                                    padding: '8px 16px',
                                    borderRadius: '12px',
                                    '&:hover': {
                                        backgroundColor: '#b6d9ee',
                                    },
                                }}
                            >
                                Действия
                            </Button>
                            {/* Меню действий */}
                            <Menu
                                anchorEl={anchorEl}
                                open={Boolean(anchorEl)}
                                onClose={handleMenuClose}
                                PaperProps={{
                                    sx: {
                                        width: {
                                            xs: 280,
                                            md: 200,
                                            lg: 345,
                                            xl: 314,
                                        },
                                        backgroundColor: '#f5f5f5',
                                        padding: '4px 0',
                                        boxShadow: '0px 4px 12px rgba(0, 0, 0, 0.1)',
                                    },
                                }}
                            >
                                <MenuItem onClick={(e) => handleStatusMenuOpen(e)} sx={{ textAlign: 'center', justifyContent: 'center' }}>
                                    Изменить статус заказа
                                </MenuItem>
                                <MenuItem onClick={handleDelete} sx={{ textAlign: 'center', justifyContent: 'center' }}>
                                    Удалить заказ
                                </MenuItem>
                                <MenuItem onClick={() => handleCopyOrderCode(order.order_code)} sx={{ textAlign: 'center', justifyContent: 'center' }}>
                                    {isCodeCopied ? 'Код скопирован' : `Скопировать код заказа`}
                                </MenuItem>
                            </Menu>

                            {/* Меню выбора статуса */}
                            <Menu
                                anchorEl={statusMenuAnchorEl}
                                open={Boolean(statusMenuAnchorEl)}
                                onClose={handleStatusMenuClose}
                                PaperProps={{
                                    sx: {
                                        width: statusMenuAnchorEl ? `${statusMenuAnchorEl.offsetWidth}px` : 'auto',
                                        fontWeight: 'bold',
                                    },
                                }}
                                BackdropProps={{
                                    style: {
                                        backgroundColor: 'transparent', // Делаем backdrop прозрачным
                                    },
                                }}
                            >
                                {statuses.map((status) => (
                                    <MenuItem
                                        key={status.id}
                                        onClick={() => handleStatusChange(status.id)} // Только ID статуса
                                        sx={{ textAlign: 'center', justifyContent: 'center' }}
                                    >
                                        {status.name}
                                    </MenuItem>
                                ))}
                            </Menu>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
}

export default UserOrders;