import { useState, useEffect } from 'react';
import Header from "../components/Header";
import Footer from "../components/Footer";
import Breadcrumbs from "../components/Breadcrumbs";

function Reviews() {
  const [reviews, setReviews] = useState([]);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const [loading, setLoading] = useState(false);
  const [filter, setFilter] = useState(0); // Для фильтрации по звёздам

  useEffect(() => {
    // Функция для получения отзывов с сервера
    const fetchReviews = async (isFilterChange = false) => {
      setLoading(true);
      try {
        const response = await fetch(`https://gachashop-backend.onrender.com/user-review/reviews?page=${page}&stars=${filter}`);
        const data = await response.json();

        const newReviews = Array.isArray(data.reviews) ? data.reviews : [];

        if (isFilterChange || page === 1) {
          setReviews(newReviews);
        } else {
          setReviews((prev) => [...prev, ...newReviews]);
        }

        // Если пришло меньше 10 отзывов — значит, дальше отзывов нет
        if (newReviews.length < 10) {
          setHasMore(false);
        } else {
          setHasMore(true); // если 10 — потенциально есть ещё
        }
      } catch (error) {
        console.error('Ошибка при загрузке отзывов:', error);
        setHasMore(false);
      }
      setLoading(false);
    };


    fetchReviews();
  }, [page, filter]);

  // Хлебные крошки
  const crumbs = [
    { label: 'Главная', path: '/' },
    { label: 'Отзывы', path: '/reviews' }
  ];

  // Компонент для отображения звёзд
  const StarRating = ({ rating }) => (
    <div className="flex">
      {[1, 2, 3, 4, 5].map((star) => (
        <svg
          key={star}
          xmlns="http://www.w3.org/2000/svg"
          viewBox="0 0 24 24"
          fill={star <= rating ? 'black' : 'none'}
          stroke="black"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          className="w-6 h-6"
        >
          <polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2" />
        </svg>
      ))}
    </div>
  );

  // Компонент для одной карточки отзыва
  const ReviewCard = ({ review }) => (
    <div className="bg-[#6a3fa7] pl-6 pr-4 mb-4 rounded-lg">
      <div className="flex justify-between text-sm text-right">
        <div className="flex items-center">
          <img src={review.user.avatar_url} alt="Аватар" className="w-12 h-12 rounded-full mr-4" />

          <StarRating rating={review.rating} />
        </div>
        <span className="flex items-center text-white">{new Date(review.review_date).toLocaleString('ru-RU', {
          day: '2-digit',
          month: '2-digit',
          year: 'numeric',
          hour: '2-digit',
          minute: '2-digit',
        })}</span>
      </div>
      <div className="mt-4">
        <p className="text-white font-bold">{review.user.nickname}</p>
        {review.review_text && <p className="text-white mt-2">{review.review_text}</p>}
      </div>

      {review.businessReply && (
        <div className="bg-[#976BD6] p-3 mt-4 rounded-lg">
          <div className="flex items-center mb-2">
            <img src={review.businessReply.avatar_url} alt="Аватар" className="w-8 h-8 rounded-full mr-2" />
          </div>
          <span className="text-black font-bold">{review.businessReply.nickname}</span>
          <p className="text-black">{review.businessReply.text}</p>
        </div>
      )}

      <div className="text-white text-sm mt-4">ID: {review.user.id}</div>
    </div>
  );

  return (
    <div className="bg-[#000000] font-seravek">
      <div className='w-full'>
        <Header />
        <div className="container flex flex-row justify-between mx-auto pl-6 pr-4 md:pl-11 mt-[30px]">
          <Breadcrumbs crumbs={crumbs} />

          <div>
            <select
              className="bg-[#4E2982] text-white p-2 rounded"
              onChange={(e) => setFilter(e.target.value)}
              value={filter}
            >
              <option value={0}>Все отзывы </option>
              <option value={5}>5 звёзд</option>
              <option value={4}>4 звезды</option>
              <option value={3}>3 звезды</option>
              <option value={2}>2 звезды</option>
              <option value={1}>1 звезда</option>
            </select>
          </div>
        </div>
      </div>

      <div className="flex flex-col flex-grow min-h-screen">
        <div className="container flex-grow mx-auto px-4 py-6">

          {!loading && reviews.length === 0 && (
            <p className="text-white text-center text-lg mt-10">Отзывов пока нет.</p>
          )}

          {Array.isArray(reviews) && reviews.map((review) => (
            <ReviewCard key={review.review_id} review={review} />
          ))}


          {hasMore && !loading && (
            <div className="text-center mt-6">
              <button
                onClick={() => setPage((prev) => prev + 1)}
                className="bg-[#4E2982] text-white px-6 py-2 rounded hover:bg-[#6840a0] transition"
              >
                Загрузить ещё
              </button>
            </div>
          )}
        </div>
        <Footer />
      </div>
    </div>
  );
}

export default Reviews;
