import Header from "../components/Header";
import Footer from "../components/Footer";
import Breadcrumbs from "../components/Breadcrumbs";
import { Link, useNavigate } from 'react-router-dom';
import React, { useState, useEffect } from 'react';

function GameChoose() {
  const [games, setGames] = useState([]);
  const colors = ['bg-[#F0E6C5]', 'bg-[#EBADC2]', 'bg-[#BE691F]'];

  useEffect(() => {
    const fetchGames = async () => {
      try {
        const response = await fetch('https://gachashop-backend.onrender.com/games');
        const data = await response.json();
        setGames(data);
      } catch (error) {
        console.error('Error fetching games:', error.message);
      }
    };
    fetchGames();
  }, []);

  const crumbs = [
    { label: 'Главная', path: '/' },
    { label: 'Выбор игры', path: '/gamechoose' }
  ];

  return (
    <div className="bg-[#000000] font-seravek min-h-screen flex flex-col">
      <div className="w-full">
        <Header />
        <div className="container mx-auto px-6 md:px-11 mt-2">
          <Breadcrumbs crumbs={crumbs} />
        </div>
      </div>

      <div className="container flex-grow mx-auto flex flex-col">
        <div className="flex flex-col flex-grow lg:flex-row justify-center items-center gap-4 mt-6">
          {games.map((game, index) => (
            <div
              className={`lg:my-4 bg-[#FFFFFF] rounded-lg overflow-hidden lg:grayscale lg:hover:scale-105 hover:grayscale-0 ease-in-out duration-300 animate-fade-in`}
              key={game.id}
            >
              <AnimatedCard game={game} index={index} colors={colors} />
            </div>
          ))}
        </div>
      </div>
      <Footer />
    </div>
  );
}

function AnimatedCard({ game, index, colors }) {
  const [isAnimated, setIsAnimated] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    const delay = index * 0.4;
    setTimeout(() => {
      setIsAnimated(true);
    }, delay * 1000);
  }, [index]);

  const handleClick = () => {
    navigate('/catalog', { state: { gameId: game.id } });
  };

  return (
    <div
      className={`lg:w-[280px] xl:w-[320px] bg-[#FFFFFF] rounded-lg overflow-hidden lg:grayscale lg:hover:scale-105 hover:grayscale-0 ease-in-out duration-300 ${isAnimated ? 'animate-fade-in' : ''}`}
      style={{ opacity: isAnimated ? 1 : 0 }}
      onClick={handleClick}
    >
      <Link to="/catalog">
        <img
          src={game.image}
          alt={game.name}
          className="w-40 lg:w-full h-40 lg:h-[405px] xl:h-[533px] object-cover"
        />
        <div className={`flex justify-center items-center sm:h-8 lg:h-[145px] xl:h-[117px] ${colors[index % colors.length]}`}>
          <p className="text-center text-[#FFFFFF] drop-shadow-[0_1.2px_1.2px_rgba(0,0,0,0.8)] sm:text-base lg:text-2xl xl:text-3xl uppercase">{game.name}</p>
        </div>
      </Link>
    </div>
  );
}

export default GameChoose;