import Header from "../components/Header";
import Footer from "../components/Footer";
import { Link } from "react-router-dom";
import React, { useState, useEffect } from 'react';
import Banner from "../components/images/Banner.png";
import Wave from "../components/images/Lines/sea-waves.png";
import Spiral from "../components/images/Lines/spiral.png";

function Home() {
  const [showContent, setShowContent] = useState(false);
  const [showHeartbeat, setShowHeartbeat] = useState(false);

  useEffect(() => {
    const timeoutId = setTimeout(() => {
      setShowContent(true);
    }, 50);

    return () => clearTimeout(timeoutId);
  }, []);

  useEffect(() => {
    if (window.location.pathname === '/') {
      const timeoutId = setTimeout(() => {
        setShowHeartbeat(true);
      }, 500);

      return () => clearTimeout(timeoutId);
    }
  }, []);

  return (
    <div className="bg-[#000000] text-[#FFFFFF] font-seravek min-h-screen flex flex-col">
      <Header />

      <div className="flex flex-col flex-grow">
        <div className='container flex flex-grow justify-center items-center mx-auto'>
          <div className={`content ${showContent ? 'opacity-100 translate-x-0 flex sm:flex-col-reverse lg:flex-row items-center justify-center ease-in-out duration-1000' : 'opacity-0 translate-x-[-80px]'}`}>

            <div className="flex flex-col">
              <div className="sm:w-[20rem] md:w-full lg:w-[25rem] xl:w-[40rem]">
                <div className="sm:hidden lg:block lg:text-3xl xl:text-6xl font-bold">
                  <p>
                    ПОКУПАЙТЕ ДОНАТ
                    <br></br>
                    ВЫГОДНО И
                    <br></br>
                    НАДЕЖНО С НАМИ!
                  </p>
                </div>

                <div className="lg:hidden text-xl text-center font-bold">
                  <p>
                    ПОКУПАЙТЕ ДОНАТ
                    ВЫГОДНО И
                    НАДЕЖНО С НАМИ!
                  </p>
                </div>

                <div className="sm:text-base sm:text-center lg:text-base lg:text-left xl:text-lg font-bold mt-4">
                  Мы никогда не запрашиваем ваши данные от игры!
                  <br />
                  Вы получаете универсальный код сразу после
                  оплаты!
                  <br />
                  <br />
                  А с нашей системой кэшбека ваши покупки станут выгоднее.
                  <br />
                  Оплатить можно до <span className="underline underline-offset-4">100%</span> от суммы покупки!
                </div>

                <div className="flex flex-row sm:justify-center lg:justify-normal space-x-10 md:space-x-20 lg:space-x-10 mt-10">
                  <Link to="/gamechoose">
                    <span className="p-1 md:p-4 lg:p-4 xl:p-6 text-sm md:text-base xl:text-2xl text-[#976BD6] border border-[#976BD6] hover:bg-[#976BD6] hover:text-[#000000] ease-in-out duration-200 rounded">
                      Перейти в каталог
                    </span>
                  </Link>
                  <Link to="/faq">
                    <span className="p-1 md:p-4 lg:p-4 xl:p-6 text-sm md:text-base xl:text-2xl text-[#976BD6] border border-[#976BD6] hover:bg-[#976BD6] hover:text-[#000000] ease-in-out duration-200 rounded">
                      Узнать больше о нас
                    </span>
                  </Link>
                </div>
              </div>
            </div>

            <div>
              <div className="flex flex-row justify-between sm:mb-10 md:mb-20 lg:mb-0">
                <div className="flex flex-col justify-between">
                  <img src={Wave} alt="Волна" className="animate-waveb sm:w-6 md:w-10 lg:w-12 xl:w-14 rotate-[142deg]" />
                  <img src={Spiral} alt="Спираль" className="animate-spiral sm:w-6 md:w-10 lg:w-12 xl:w-14" />
                </div>

                <img src={Banner} alt="Баннер" className={`heart sm:w-[14rem] md:w-[18rem] lg:w-[25rem] xl:w-[30rem]
                ${showHeartbeat ? 'animate-heartbeat' : ''}`} />

                <img src={Wave} alt="Волна" className="animate-wavel sm:h-8 md:h-12 lg:h-14 xl:h-16 rotate-[27deg]" />
              </div>
            </div>
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
}

export default Home;