import Header from "../components/Header";
import Footer from "../components/Footer";
import React, { useState, useContext, useEffect } from 'react';
import { useNavigate, useLocation } from "react-router-dom";
import Register from "../components/Register";
import Login from "../components/Login";
import { toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import back from "../components/images/Register_and_Auth/back-button.png";
import { UserContext } from "../components/Context"; // Импортируем контекст

function Authentication() {
    const token = localStorage.getItem('token');
    const { user, logout, updateUser } = useContext(UserContext); // Извлекаем updateUser из контекста
    const location = useLocation();
    const queryParams = new URLSearchParams(location.search);
    const initialForm = queryParams.get('form') || 'register';
    const [overlayClass, setOverlayClass] = useState(null);
    const [showRegister, setShowRegister] = useState(initialForm === 'register');
    const [formVisible, setFormVisible] = useState(true); // для fade-in
    const navigate = useNavigate();
    const [isMobile, setIsMobile] = useState(false);
    const [mobileOverlayClass, setMobileOverlayClass] = useState(null);

    useEffect(() => {
        const checkMobile = () => {
            const width = window.innerWidth;
            setIsMobile(width < 1024); // sm & md: мобильные, <1024px
        };

        checkMobile();
        window.addEventListener('resize', checkMobile);
        return () => window.removeEventListener('resize', checkMobile);
    }, []);

    const handleSwitchForm = () => {
        if (isMobile) {
            setFormVisible(false);

            if (showRegister) {
                // Переключаемся на Login — анимация слева направо
                setMobileOverlayClass('mobile-overlay start-left');
                setTimeout(() => {
                    setMobileOverlayClass('mobile-overlay animate-in');
                }, 10);

                setTimeout(() => {
                    setShowRegister(false);
                }, 300);

                setTimeout(() => {
                    setMobileOverlayClass('mobile-overlay animate-out-right');
                }, 350);

            } else {
                // Переключаемся на Register — анимация справа налево
                setMobileOverlayClass('mobile-overlay start-right');
                setTimeout(() => {
                    setMobileOverlayClass('mobile-overlay animate-in');
                }, 10);

                setTimeout(() => {
                    setShowRegister(true);
                }, 300);

                setTimeout(() => {
                    setMobileOverlayClass('mobile-overlay animate-out-left');
                }, 350);
            }

            setTimeout(() => {
                setMobileOverlayClass(null);
                setFormVisible(true);
            }, 600);
        } else {
            // Desktop-анимация (оставляем как было)
            const isRegisterNow = showRegister;
            const from = isRegisterNow ? 'left' : 'right';
            const to = isRegisterNow ? 'right' : 'left';

            setFormVisible(false);
            setOverlayClass(`full-overlay start-${from}`);
            setTimeout(() => setOverlayClass('full-overlay slide-in'), 10);
            setTimeout(() => setShowRegister(!isRegisterNow), 400);
            setTimeout(() => setOverlayClass(`full-overlay slide-out-${to}`), 420);
            setTimeout(() => {
                setOverlayClass(null);
                setFormVisible(true);
            }, 800);
        }
    };

    const handleRegisterSubmit = async (data) => {
        try {
            const response = await fetch('https://gachashop-backend.onrender.com/register', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${token}`
                },
                body: JSON.stringify(data),
            });

            const responseData = await response.json();

            if (response.ok && responseData.status === 'success') {
                toast.success('Регистрация прошла успешно!');
                setShowRegister(false);
            } else {
                toast.error(`Ошибка регистрации: ${responseData.message || 'Неизвестная ошибка'}`);
            }
        } catch (error) {
            toast.error(`Ошибка регистрации: ${error.message}`);
            console.error('Ошибка при отправке данных:', error);
        }
    };

    const handleLoginSubmit = async (data) => {
        try {
            const response = await fetch('https://gachashop-backend.onrender.com/register/login', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(data),
            });

            const responseData = await response.json();

            if (response.ok && responseData.status === 'success') {
                toast.success('Вход выполнен успешно!');
                localStorage.setItem('token', responseData.token);

                // Получаем данные пользователя с новым токеном
                const userResponse = await fetch('https://gachashop-backend.onrender.com/user/me', {
                    method: 'GET',
                    headers: {
                        'Content-Type': 'application/json',
                        'Authorization': `Bearer ${responseData.token}`,
                    },
                });

                if (userResponse.ok) {
                    const userData = await userResponse.json();
                    updateUser(userData);
                }

                // Навигация
                const redirectTo = new URLSearchParams(location.search).get('redirectTo');
                if (redirectTo) {
                    navigate(redirectTo);
                } else {
                    navigate('/settings/personal-info');
                }
            } else {
                toast.error(`Ошибка входа: ${responseData.message || 'Неверные данные'}`);
            }
        } catch (error) {
            toast.error(`Ошибка входа: ${error.message}`);
        }
    };

    // Функция для обработки нажатия на кнопку "Назад"
    const handleBackClick = () => {
        navigate(-1);  // Возвращаемся на предыдущую страницу
    };

    return (
        <div className="bg-[#000000] font-seravek min-h-screen flex flex-col">
            <Header user={user} onLogout={logout} />

            <div className="flex flex-col flex-grow">
                <div className="container flex-grow mx-auto">

                    <div className="flex flex-col justify-center items-center">

                        {/* Кнопка назад */}
                        <div className="w-full pl-6 md:pl-28 lg:pl-12 xl:pl-32 mb-4">
                            <button onClick={handleBackClick} className="ease-in-out duration-200 hover:scale-125">
                                <img src={back} alt="Стрелка назад" className="w-8 lg:w-10" />
                            </button>
                        </div>

                        <div className="relative mb-10 overflow-hidden">

                            {/* Панели: десктоп и мобилка */}
                            {overlayClass && !isMobile && <div className={overlayClass} />}
                            {mobileOverlayClass && isMobile && <div className={mobileOverlayClass} />}

                            {/* Форма */}
                            <div className={`w-full h-full transition-all duration-400 ${formVisible ? 'form-fade visible' : 'form-fade'}`}>
                                {showRegister ? (
                                    <Register onSwitchToLogin={handleSwitchForm} onSubmit={handleRegisterSubmit} />
                                ) : (
                                    <Login onSwitchToRegister={handleSwitchForm} onSubmit={handleLoginSubmit} />
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            <Footer />
        </div>
    );
}

export default Authentication;