import { useLocation, useNavigate, Link } from 'react-router-dom';
import { useEffect } from 'react';
import Header from "../components/Header";
import Footer from "../components/Footer";
import 'react-toastify/dist/ReactToastify.css';
import { useUserContext } from "../components/Context";
import { toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

import back from "../components/images/Register_and_Auth/back-button.png";

function Success() {
    const location = useLocation();
    const params = new URLSearchParams(location.search);
    const code = params.get('code');

    const { user, loading } = useUserContext();
    const navigate = useNavigate();

    useEffect(() => {
        if (!loading && !user) {
            navigate('/');
        }
    }, [user, loading, navigate]);

    if (loading) {
        return <div className="text-white text-center mt-10">Загрузка...</div>;
    }

    const copyToClipboard = async () => {
        try {
            await navigator.clipboard.writeText(code);
            toast.success('Код успешно скопирован!', {
                position: 'bottom-right', // Задаем позицию уведомления строкой
                autoClose: 2000,
            });
        } catch (err) {
            console.error('Ошибка копирования:', err);
            toast.error('Не удалось скопировать код. Попробуйте другой браузер или проверьте права доступа.', {
                position: 'top-right',
            });
        }
    };

    return (
        <div className="bg-[#000000] font-seravek min-h-screen flex flex-col">
            <div className='w-full'>
                <Header />
                {/* Кнопка назад */}
                <div className="container mx-auto px-6 md:px-11 mt-[30px]">
                    <Link to="/catalog" className="flex items-center space-x-[10px]">
                        <img src={back} alt="Стрелка назад" className="w-4 xl:w-6" />
                        <span className="text-lg xl:text-xl text-[#FFFFFF]">Вернуться в магазин</span>
                    </Link>
                </div>
            </div>
            <div className="flex flex-col flex-grow px-2 xl:px-0">
                <div className="container flex flex-col justify-center mx-auto flex-grow">
                    <div className='text-white flex flex-col text-lg md:text-xl lg:text-2xl justify-center items-center'>
                        <div className='flex flex-col text-center pb-10 font-bold'>
                            <p>Оплата прошла успешно!</p>
                        </div>

                        <p className='pb-[50px] text-center'>Ваш код для ввода в игру:
                            <br className='lg:hidden' />
                            <strong className='text-[#976BD6] hover:cursor-pointer hover:underline underline-offset-[5px]' onClick={copyToClipboard}> {code}</strong>
                        </p>

                        <p className='text-center text-base md:text-lg lg:text-xl'>Запишите код и не передавайте его никому!</p>
                        <p className='text-center mb-4 xl:mb-5 text-base md:text-lg lg:text-xl'>По вопросам, касаемых заказа, просим обращаться в поддержку магазина</p>

                        <Link to={`/user-review?code=${code}`} className='flex px-2 md:px-4 lg:px-10 py-1 md:py-2 rounded-md justify-center items-center text-center text-black text-lg lg:text-xl bg-[#976BD6] hover:bg-[#684a91] ease-in-out duration-200'>
                            Оставить отзыв
                        </Link>
                    </div>
                </div>
            </div>
            <Footer />
        </div>
    );
}

export default Success;
