import { useState, useEffect } from 'react';


// Функция для получения данных пользователя по его ID
async function fetchUserDataById(userId) {
    const token = localStorage.getItem('token');
    try {
        const response = await fetch(`https://gachashop-backend.onrender.com/user/get-by-id?id=${userId}`, {
            method: 'GET',
            headers: {
                'Authorization': `Bearer ${token}`,
            },
        });
        if (!response.ok) {
            throw new Error('Ошибка получения данных пользователя');
        }
        const data = await response.json();
        return data;
    } catch (error) {
        console.error('Error fetching user data by ID:', error);
        return null;
    }
}

async function fetchAdminData() {
    const token = localStorage.getItem('token'); // Получаем JWT из localStorage

    try {
        const response = await fetch('https://gachashop-backend.onrender.com/user/get-user-data', {
            method: 'GET',
            headers: {
                'Authorization': `Bearer ${token}`,  // Вставляем токен в заголовок
            },
        });

        if (!response.ok) {
            throw new Error(`Ошибка: ${response.status}`);
        }

        const data = await response.json();
        return data;
    } catch (error) {
        console.error('Error fetching admin data:', error);
        return null;
    }
}

async function fetchReviews() {
    const token = localStorage.getItem('token');  // Получаем токен из localStorage

    try {
        const response = await fetch('https://gachashop-backend.onrender.com/user-review/get-all', {
            method: 'GET',
            headers: {
                'Authorization': `Bearer ${token}`,  // Передаем токен в заголовке
            },
        });

        if (!response.ok) {
            throw new Error(`Ошибка: ${response.status}`);
        }

        const data = await response.json();
        return data;
    } catch (error) {
        console.error('Error fetching reviews:', error);
        return [];
    }
}

async function submitAdminResponse(reviewId, responseText) {
    const token = localStorage.getItem('token'); // Получаем токен из localStorage

    try {
        const response = await fetch(`https://gachashop-backend.onrender.com/user-review/submit-reply`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${token}`, // Отправляем токен в заголовке
            },
            body: JSON.stringify({
                review_id: reviewId,
                text: responseText,
            }),
        });
        const data = await response.json();
        return data;
    } catch (error) {
        console.error('Error submitting admin response:', error);
        return null;
    }
}

async function deleteAdminResponse(reviewId) {
    const token = localStorage.getItem('token'); // Получаем JWT

    try {
        const response = await fetch(`https://gachashop-backend.onrender.com/user-review/delete-reply/${reviewId}`, {
            method: 'DELETE',  // Используем DELETE напрямую
            headers: {
                'Authorization': `Bearer ${token}`,  // Передаем токен
                'Content-Type': 'application/json', // Не обязательно для DELETE без тела, можно убрать
            },
        });
        const data = await response.json();
        return data;
    } catch (error) {
        console.error('Error deleting admin response:', error);
        return null;
    }
}


function ReviewManagement() {
    const [reviews, setReviews] = useState([]);
    const [responseTexts, setResponseTexts] = useState({});
    const [filterByAnswer, setFilterByAnswer] = useState(false);
    const [adminId, setAdminId] = useState(null);
    const [userInfo, setUserInfo] = useState({});
    const [isEditing, setIsEditing] = useState({});
    const [sortByDate, setSortByDate] = useState(''); // '' | 'asc' | 'desc'

    useEffect(() => {
        const loadAdminData = async () => {
            const adminData = await fetchAdminData();
            if (adminData && adminData.is_admin === 1) {
                setAdminId(adminData.id);
            }
        };
        loadAdminData();
    }, []);

    useEffect(() => {
        const loadReviewsAndUserInfo = async () => {
            const reviewsData = await fetchReviews();
            setReviews(reviewsData);


            for (let review of reviewsData) {
                if (review.user_id) {
                    const userData = await fetchUserDataById(review.user_id);
                    setUserInfo((prev) => ({
                        ...prev,
                        [review.user_id]: userData,
                    }));
                }
            }
        };

        loadReviewsAndUserInfo();
    }, []);

    const handleResponseChange = (reviewId, text) => {
        setResponseTexts((prev) => ({
            ...prev,
            [reviewId]: text,
        }));
    };

    const handleResponseSubmit = async (reviewId) => {
        const responseTextForReview = responseTexts[reviewId];
        if (responseTextForReview?.trim() && adminId) {
            const result = await submitAdminResponse(reviewId, responseTextForReview.trim());
            if (result && result.success) {
                setReviews((prevReviews) => {
                    return prevReviews.map((review) => {
                        if (review.id === reviewId) {
                            return {
                                ...review,
                                admin_answer: result.data,
                            };
                        }
                        return review;
                    });
                });
                setResponseTexts((prev) => ({
                    ...prev,
                    [reviewId]: '',
                }));
                setIsEditing((prev) => ({
                    ...prev,
                    [reviewId]: false,  // Выключаем режим редактирования после отправки
                }));
            }
        }
    };

    const handleEditResponse = (reviewId) => {
        setIsEditing((prev) => ({
            ...prev,
            [reviewId]: true,  // Включаем режим редактирования
        }));
        setResponseTexts((prev) => ({
            ...prev,
            [reviewId]: reviews.find((r) => r.id === reviewId)?.admin_answer?.text || '',
        }));
    };

    const handleDeleteResponse = async (reviewId) => {
        const result = await deleteAdminResponse(reviewId);
        if (result) {
            const updatedReviews = await fetchReviews();
            setReviews(updatedReviews);
        }
    };

    const filteredReviews = reviews
        .filter((review) => {
            if (filterByAnswer) {
                return !review.admin_answer;
            }
            return true;
        })
        .sort((a, b) => {
            // Сортировка по дате
            if (sortByDate === 'asc') {
                return new Date(a.created_at) - new Date(b.created_at);
            } else if (sortByDate === 'desc') {
                return new Date(b.created_at) - new Date(a.created_at);
            }

            return 0;
        });

    return (
        <div className="review-management">
            <h2 className="pl-2 lg:pl-4 text-left font-bold text-2xl lg:text-3xl mb-10">Управление отзывами</h2>

            <div className="flex flex-col md:flex-row lg:flex-col md:w-full md:justify-start md:items-center lg:items-start space-y-4 md:space-y-0 lg:space-y-4 md:space-x-4 lg:space-x-0 mb-10 lg:pl-4">
                <div>
                    <select
                        value={sortByDate}
                        onChange={(e) => setSortByDate(e.target.value)}
                        className="border p-2 rounded-2xl text-black focus:ring-2 focus:ring-main-purple text-center w-full md:w-48"
                    >
                        <option value="">Без сортировки</option>
                        <option value="asc">По дате ↑</option>
                        <option value="desc">По дате ↓</option>
                    </select>
                </div>

                <div className='w-full md:w-56 flex justify-center md:justify-normal'>
                    <button
                        type="button"
                        onClick={() => setFilterByAnswer(!filterByAnswer)}
                        className={`w-56 px-[10px] py-[5px] text-[15px] rounded-md text-white text-center ${filterByAnswer ? 'border-2 border-[#976BD6] bg-[#6A4BAF]' : 'border-2 border-[#6A4BAF] bg-[#6A4BAF]'} hover:bg-[#7D5FD0]`}
                    >
                        Только отзывы без ответов
                    </button>
                </div>
            </div>

            <ul className="space-y-4 lg:mx-4">
                {filteredReviews.map((review) => (
                    <li key={review.id} className="border p-4 rounded-lg">
                        <div className="flex items-center space-x-4">
                            <div className="flex items-center space-x-2">
                                {userInfo[review.user_id]?.avatar_url ? (
                                    <img
                                        src={userInfo[review.user_id].avatar_url}
                                        alt="User Avatar"
                                        className="w-8 h-8 rounded-full"
                                    />
                                ) : (
                                    <div className="w-8 h-8 rounded-full bg-gray-400 text-white flex items-center justify-center text-sm font-bold">
                                        А
                                    </div>
                                )}
                                <p className="font-semibold">{userInfo[review.user_id]?.nickname || 'Пользователь не загружен'}</p>
                            </div>
                        </div>
                        <p><strong>Оценка:</strong> {review.review}/5</p>
                        <p><strong>Текст отзыва:</strong> {review.text || 'Отсутствует'}</p>
                        {review.admin_answer ? (
                            <div>
                                <p><strong>Ответ администратора:</strong> {review.admin_answer.text}
                                </p>
                                {review.admin_answer.admin_id === adminId && !isEditing[review.id] && (
                                    <div className="flex space-x-2 mt-2">
                                        <button
                                            onClick={() => handleEditResponse(review.id)}
                                            className="bg-transparent border border-menu-purple text-menu-purple p-2 rounded-xl mt-2 hover:bg-menu-purple hover:text-black ease-in-out duration-100"
                                        >
                                            Редактировать ответ
                                        </button>
                                        <button
                                            onClick={() => handleDeleteResponse(review.id)}
                                            className="bg-transparent border border-red-400 text-red-400 p-2 rounded-xl mt-2 hover:bg-red-400 hover:text-black ease-in-out duration-100"
                                        >
                                            Удалить ответ
                                        </button>
                                    </div>
                                )}
                            </div>
                        ) : (
                            adminId && (
                                <div className="flex flex-col mt-2">
                                    <textarea
                                        value={responseTexts[review.id] || ''}
                                        onChange={(e) => handleResponseChange(review.id, e.target.value)}
                                        placeholder="Введите ваш ответ"
                                        className="border-0 p-2 w-full text-black focus:ring-0 focus:ring-offset-0"
                                    />
                                    <button
                                        onClick={() => handleResponseSubmit(review.id)}
                                        className="w-full md:w-64 bg-transparent border border-menu-purple text-menu-purple p-2 rounded-xl mt-2 hover:bg-menu-purple hover:text-black ease-in-out duration-100"
                                    >
                                        Отправить ответ
                                    </button>
                                </div>
                            )
                        )}


                        {isEditing[review.id] && review.admin_answer && (
                            <div className="mt-2">
                                <textarea
                                    value={responseTexts[review.id] || ''}
                                    onChange={(e) => handleResponseChange(review.id, e.target.value)}
                                    placeholder="Редактируйте ваш ответ"
                                    className="border-0 p-2 w-full text-black focus:ring-0 focus:ring-offset-0"
                                />
                                <button
                                    onClick={() => handleResponseSubmit(review.id)}
                                    className="w-full md:w-64 bg-transparent border border-menu-purple text-menu-purple p-2 rounded-xl mt-2 hover:bg-menu-purple hover:text-black ease-in-out duration-100"
                                >
                                    Сохранить изменения
                                </button>
                            </div>
                        )}
                    </li>
                ))}
            </ul>
        </div>
    );
}

export default ReviewManagement;