import React, { useEffect, useState } from 'react'; // Добавить useContext
import { useNavigate, Link, Outlet, useLocation } from 'react-router-dom';
import { useUserContext } from '../components/Context';
import Header from '../components/Header';
import Footer from '../components/Footer';
import personal_white from "../components/images/Settings-menu/white/add-friend.png";
import payment_white from "../components/images/Settings-menu/white/credit-card.png";
import history_white from "../components/images/Settings-menu/white/list.png";
import exit_white from "../components/images/Settings-menu/white/shutdown.png";
import password_white from "../components/images/Settings-menu/white/unlock.png";
import admin_white from "../components/images/Settings-menu/white/setting.png";

import personal_black from "../components/images/Settings-menu/black/add-friend.png";
import payment_black from "../components/images/Settings-menu/black/credit-card.png";
import history_black from "../components/images/Settings-menu/black/list.png";
import password_black from "../components/images/Settings-menu/black/unlock.png";

// Функция для получения данных пользователя
async function fetchUserData() {
    const token = localStorage.getItem('token');
    if (!token) return null;

    try {
        const response = await fetch('https://gachashop-backend.onrender.com/user/get-user-data', {
            method: 'GET',
            headers: {
                'Authorization': `Bearer ${token}`,
                'Content-Type': 'application/json',
            },
        });
        if (!response.ok) return null;
        const data = await response.json();
        return data;
    } catch (error) {
        console.error('Ошибка при получении данных пользователя:', error);
        return null;
    }
}

function AccountSettings() {
    const [isAdmin, setIsAdmin] = useState(false);
    const [loading, setLoading] = useState(true);
    const navigate = useNavigate();
    const location = useLocation();
    const { logout } = useUserContext();

    useEffect(() => {
        const checkUserAdminStatus = async () => {
            const userData = await fetchUserData();
            if (!userData) {
                navigate('/'); // Если данные не получены, перенаправляем на главную
                return;
            }

            if (userData.is_admin === 1) {
                setIsAdmin(true); // Пользователь администратор
            }

            setLoading(false); // Завершаем загрузку
        };

        checkUserAdminStatus();
    }, [navigate]);

    const handleLogout = async () => {
        await logout();
        navigate('/auth?form=login');
    };

    const isActive = (path) => {
        return location.pathname.includes(path) ? 'bg-[#af7cf7] text-black' : 'text-white bg-[#6e6e6e] hover:bg-[#684a91] ease-in-out duration-200';
    };

    const getIcon = (whiteIcon, blackIcon, path) => {
        return location.pathname.includes(path) ? blackIcon : whiteIcon;
    };

    if (loading) {
        return <div>Загрузка...</div>; // Показать индикатор загрузки
    }

    return (
        <div className="bg-[#000000] font-seravek min-h-screen flex flex-col">
            <Header />
            <div className="flex flex-col flex-grow text-white">
                <div className="container flex flex-col lg:flex-row flex-grow mx-auto mt-10">
                    <aside className="sidebar">
                        <ul className='mb-4 lg:mb-0 space-y-2'>
                            <li className='flex'>
                                <Link
                                    to="personal-info"
                                    className={`py-1 md:py-2 lg:pl-4 lg:pr-20 rounded-xl flex flex-grow justify-center lg:justify-normal items-center ${isActive('personal-info')}`}
                                >
                                    <img
                                        src={getIcon(personal_white, personal_black, 'personal-info')}
                                        alt="Персональная информация"
                                        className='w-6 lg:w-8 mr-2'
                                    />
                                    Персональная информация
                                </Link>
                            </li>
                            <li>
                                <Link
                                    to="order-history"
                                    className={`py-1 md:py-2 lg:pl-4 lg:pr-20 rounded-xl flex flex-grow justify-center lg:justify-normal items-center ${isActive('order-history')}`}
                                >
                                    <img
                                        src={getIcon(history_white, history_black, 'order-history')}
                                        alt="История заказов"
                                        className='w-6 lg:w-8 mr-2'
                                    />
                                    История заказов
                                </Link>
                            </li>
                            <li>
                                <Link
                                    to="payment-methods"
                                    className={`py-1 md:py-2 lg:pl-4 lg:pr-20 rounded-xl flex flex-grow justify-center lg:justify-normal items-center ${isActive('payment-methods')}`}
                                >
                                    <img
                                        src={getIcon(payment_white, payment_black, 'payment-methods')}
                                        alt="Способы оплаты"
                                        className='w-6 lg:w-8 mr-2'
                                    />
                                    Способы оплаты
                                </Link>
                            </li>
                            <li>
                                <Link
                                    to="change-password"
                                    className={`py-1 md:py-2 lg:pl-4 lg:pr-20 rounded-xl flex flex-grow justify-center lg:justify-normal items-center ${isActive('change-password')}`}
                                >
                                    <img
                                        src={getIcon(password_white, password_black, 'change-password')}
                                        alt="Изменить пароль"
                                        className='w-6 lg:w-8 mr-2'
                                    />
                                    Изменить пароль
                                </Link>
                            </li>

                            {isAdmin && (
                                <li>
                                    <Link
                                        to="/admin"
                                        className="py-1 md:py-2 lg:pl-4 lg:pr-20 rounded-xl flex flex-grow justify-center lg:justify-normal items-center text-white bg-[#6e6e6e] hover:bg-[#684a91] ease-in-out duration-200"
                                    >
                                        <img
                                            src={admin_white}
                                            alt="Админ-панель"
                                            className='w-6 lg:w-8 mr-2'
                                        />
                                        Админ-панель
                                    </Link>
                                </li>
                            )}

                            <li>
                                <button
                                    onClick={handleLogout}
                                    className="flex flex-grow items-center w-full py-1 md:py-2 lg:pl-4 lg:pr-20 rounded-xl justify-center lg:justify-normal text-white text-start bg-[#6e6e6e] hover:bg-[#684a91] ease-in-out duration-200"
                                >
                                    <img
                                        src={exit_white}
                                        alt="Выйти из аккаунта"
                                        className='w-6 lg:w-8 mr-2'
                                    />
                                    Выйти из аккаунта
                                </button>
                            </li>
                        </ul>
                    </aside>

                    <main className="flex-grow px-4 lg:px-10 border-t lg:border-t-0 border-white flex flex-col lg:items-start">
                        <Outlet />
                    </main>
                </div>
            </div>
            <Footer />
        </div>
    );
}

export default AccountSettings;