import { useEffect, useState, useCallback, useRef } from 'react';
import { Search } from "lucide-react";
import { toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

async function fetchGames() {
    try {
        const response = await fetch('https://gachashop-backend.onrender.com/games', {
            method: 'GET',
        });
        const data = await response.json();
        return data;
    } catch (error) {
        console.error('Ошибка при получении игр:', error);
        return [];
    }
}

async function fetchProducts() {
    try {
        const response = await fetch('https://gachashop-backend.onrender.com/products', {
            method: 'GET',
        });
        const data = await response.json();
        return data;
    } catch (error) {
        console.error('Ошибка при получении товаров:', error);
        return [];
    }
}

async function deleteProduct(productId) {
    const token = localStorage.getItem('token');

    if (!token) {
        toast.error('Токен авторизации не найден');
        return false;
    }

    try {
        const response = await fetch(`https://gachashop-backend.onrender.com/products/delete/${productId}`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${token}`,
            },
            body: JSON.stringify({ _method: 'DELETE' }),
        });

        if (response.ok) {
            const data = await response.json();
            if (data.status === 'success') {
                toast.success('Товар удалён');
                return true;
            } else {
                toast.error(data.message || 'Ошибка при удалении товара');
                return false;
            }
        } else {
            toast.error('Ошибка при удалении товара');
            return false;
        }
    } catch (error) {
        console.error('Ошибка при удалении товара:', error);
        toast.error('Ошибка при удалении товара');
        return false;
    }
}


const uploadImageToCloudinary = async (file) => {
    const formData = new FormData();
    formData.append('file', file);
    formData.append('upload_preset', 'avatars_default');  // Укажите ваш preset для Cloudinary

    try {
        const response = await fetch('https://api.cloudinary.com/v1_1/dhicjidvw/image/upload', {
            method: 'POST',
            body: formData,
        });

        if (!response.ok) {
            throw new Error('Ошибка загрузки изображения');
        }

        const data = await response.json();
        if (data.secure_url) {
            return data.secure_url; // Вернем URL изображения
        } else {
            throw new Error('Не удалось получить URL изображения');
        }
    } catch (error) {
        console.error('Ошибка загрузки изображения:', error);
        throw new Error('Ошибка загрузки изображения');
    }
};

function ProductManagement() {
    const [games, setGames] = useState([]);
    const [products, setProducts] = useState([]);
    const [filteredProducts, setFilteredProducts] = useState([]);
    const [selectedGame, setSelectedGame] = useState('');
    const [selectedType, setSelectedType] = useState(''); // Тип товара (подписка или пак)
    const [selectedProduct, setSelectedProduct] = useState(null);  // Состояние для редактируемого товара
    const [sortOrder, setSortOrder] = useState('asc'); // Порядок сортировки
    const [newProduct, setNewProduct] = useState({
        name: '',
        description: '',
        image: '',
        game_id: '',
        price: '',
        type: 'sub',  // По умолчанию тип - подписка
        quantity: '',
        days: '',
    });
    const [imageFile, setImageFile] = useState(null);
    const [modalMode, setModalMode] = useState('');
    const [showModal, setShowModal] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const [searchQuery, setSearchQuery] = useState(''); // Состояние для поиска
    const backdropClickRef = useRef(false);

    useEffect(() => {
        // Загрузка игр и товаров при монтировании компонента
        const loadGamesAndProducts = async () => {
            const gamesData = await fetchGames();
            const productsData = await fetchProducts();

            setGames(gamesData);
            setProducts(productsData);
            setFilteredProducts(productsData);
        };

        loadGamesAndProducts();
    }, []); // Этот useEffect сработает только при монтировании компонента

    const handleGameFilter = (e) => {
        const gameId = e.target.value;
        setSelectedGame(gameId);

        // Фильтрация по выбранной игре
        const filtered = products.filter((product) => {
            return gameId === '' || product.game_id === parseInt(gameId);
        });

        // Применяем сортировку по возрастанию
        const sortedAndGroupedProducts = sortProducts(filtered, 'asc', selectedType);
        setFilteredProducts(sortedAndGroupedProducts);
    };

    const handleTypeFilter = (e) => {
        const type = e.target.value;
        setSelectedType(type);

        // Фильтрация по выбранному типу
        const filtered = products.filter((product) => {
            return type === '' || product.type === (type === 'Подписка' ? 'sub' : 'pack');
        });

        // Применяем сортировку по выбранному типу
        const sortedAndGroupedProducts = sortProducts(filtered, sortOrder, type);
        setFilteredProducts(sortedAndGroupedProducts);
    };

    const applyFilters = useCallback((gameId, type, order) => {
        let filtered = products;

        if (!filtered || filtered.length === 0) return; // Добавляем проверку, чтобы избежать ошибок, если данные не загружены

        if (gameId) {
            filtered = filtered.filter((product) => product.game_id === parseInt(gameId));
        }

        if (type) {
            filtered = filtered.filter((product) => product.type === (type === 'Подписка' ? 'sub' : 'pack'));
        }

        // Применяем сортировку
        const sortedProducts = sortProducts(filtered, order, type);
        setFilteredProducts(sortedProducts);
    }, [products]); // Указываем зависимости, чтобы мемоизировать функцию    

    const sortProducts = (products, order, type) => {
        const sortedProducts = [...products].sort((a, b) => {
            // Сначала группируем подписки, потом паки
            if (a.type !== b.type) {
                return a.type === 'sub' ? -1 : 1;
            }

            // Сортировка по возрастанию или убыванию для подписок и паков
            if (type === 'Подписка') {
                // Если 'days' число, можно сразу сравнивать
                return order === 'asc' ? a.days - b.days : b.days - a.days;
            } else if (type === 'Пак') {
                // Конвертируем 'quantity' в число, так как оно приходит как строка
                return order === 'asc' ? parseInt(a.quantity) - parseInt(b.quantity) : parseInt(b.quantity) - parseInt(a.quantity);
            }

            // Если тип не выбран, применяем группировку по типу и сортировку по количеству дней/валюты
            if (a.type === 'sub') {
                return order === 'asc' ? a.days - b.days : b.days - a.days;
            } else {
                return order === 'asc' ? parseInt(a.quantity) - parseInt(b.quantity) : parseInt(b.quantity) - parseInt(a.quantity);
            }
        });

        return sortedProducts;
    };

    const handleSortOrder = (e) => {
        const order = e.target.value;
        setSortOrder(order);
        applyFilters(selectedGame, selectedType, order); // Применяем сортировку
    };

    const handleAddProductClick = () => {
        setModalMode('add');          // Устанавливаем режим добавления
        setSelectedProduct(null);     // Сбрасываем выбранный продукт
        setNewProduct({
            name: '',
            image: '',
            description: '',
            game_id: '',
            price: '',
            type: 'sub',  // Теперь по умолчанию тип — 'Подписка'
            quantity: '',
            days: '',
        }); // Очищаем все поля для нового товара
        setShowModal(true);           // Открываем модальное окно
    };

    const handleEditProductClick = (product) => {
        setModalMode('edit');         // Устанавливаем режим редактирования
        setSelectedProduct(product);  // Устанавливаем продукт для редактирования
        setShowModal(true);           // Открываем модальное окно
    };

    const handleInputChange = (e) => {
        const { name, value } = e.target;

        if (modalMode === 'add') {
            setNewProduct((prev) => ({
                ...prev,
                [name]: value,
            }));
        } else if (modalMode === 'edit') {
            setSelectedProduct((prev) => ({
                ...prev,
                [name]: value,
            }));
        }
    };

    const handleFileChange = (e) => {
        setImageFile(e.target.files[0]);
    };

    const validateProduct = (product) => {
        // Проверка обязательных полей
        const { name, description, game_id, price } = product;
        if (!name || !description || !game_id || !price) {
            toast.error('Пожалуйста, заполните все обязательные поля.');
            return false;
        }
        return true;
    };

    const handleAddProduct = async () => {
        if (!validateProduct(newProduct)) {
            return;
        }

        setIsLoading(true);  // Включаем состояние загрузки сразу после нажатия кнопки
        let imageUrl = ''; // Локальная переменная для хранения URL изображения
        let days = 0;  // Значение для дней
        let quantity = "";  // Значение для количества

        // Извлекаем количество дней или quantity в зависимости от типа товара
        if (newProduct.type === 'sub') {
            days = newProduct.days ? parseInt(newProduct.days, 10) : 0;
            if (!days) {
                const extractedDays = newProduct.name.match(/\((\d+)\s*дней\)/);
                days = extractedDays ? parseInt(extractedDays[1], 10) : 0;
            }
        } else if (newProduct.type === 'pack') {
            quantity = newProduct.quantity || "";
            if (!quantity) {
                const extractedQuantity = newProduct.name.match(/(\d+)/);
                quantity = extractedQuantity ? extractedQuantity[1] : "";
            }
        }

        let priceWithRuble = newProduct.price;

        // Добавляем знак рубля через пробел, если его нет
        if (!priceWithRuble.includes(' ₽')) {
            priceWithRuble = `${priceWithRuble} ₽`;
        }

        // Проверяем, если есть файл изображения
        if (imageFile) {
            try {
                // Загружаем изображение в Cloudinary и получаем URL
                imageUrl = await uploadImageToCloudinary(imageFile);

                if (!imageUrl) {
                    toast.error('Ошибка загрузки изображения');
                    return;
                }
            } catch (error) {
                console.error('Ошибка загрузки изображения:', error);
                toast.error('Ошибка загрузки изображения');
                return;
            }
        }

        // Преобразуем данные товара и добавляем URL изображения
        const productToSave = {
            ...newProduct,
            game_id: parseInt(newProduct.game_id),
            quantity: newProduct.type === 'pack' ? quantity : "0",  // Устанавливаем извлечённое количество для типа pack
            days: newProduct.type === 'sub' ? days : 0,  // Устанавливаем извлечённое количество дней для типа sub
            price: priceWithRuble,
            image: imageUrl || newProduct.image,  // Если есть изображение, используем его
            type: newProduct.type === 'sub' ? 'sub' : 'pack', // Преобразуем тип
        };

        // Отправляем данные на сервер
        try {
            const token = localStorage.getItem('token');
            if (!token) {
                toast.error('Пользователь не авторизован');
                setIsLoading(false);
                return;
            }

            const response = await fetch('https://gachashop-backend.onrender.com/products/create', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${token}`,  // Передаем JWT
                },
                body: JSON.stringify(productToSave),
            });

            if (response.ok) {
                toast.success('Товар успешно добавлен');
                const updatedProducts = await fetchProducts();
                setProducts(updatedProducts);
                setFilteredProducts(updatedProducts);
                setShowModal(false);
            } else {
                const errorData = await response.json();
                toast.error(errorData.message || 'Ошибка добавления товара');
            }
        } catch (error) {
            console.error('Ошибка добавления товара:', error);
            toast.error('Ошибка добавления товара');
        } finally {
            setIsLoading(false);
        }
    };

    const handleEditProduct = async () => {
        setIsLoading(true);  // Включаем состояние загрузки сразу после нажатия кнопки
        let imageUrl = selectedProduct.image;  // Изначально ссылка на изображение товара, если оно есть.
        let days = 0;  // Значение для дней
        let quantity = "";  // Значение для количества

        // Извлекаем количество дней или quantity в зависимости от типа товара
        if (selectedProduct.type === 'sub') {
            days = selectedProduct.days ? parseInt(selectedProduct.days, 10) : 0;
            if (!days) {
                const extractedDays = selectedProduct.name.match(/\((\d+)\s*дней\)/);
                days = extractedDays ? parseInt(extractedDays[1], 10) : 0;
            }
        } else if (selectedProduct.type === 'pack') {
            quantity = selectedProduct.quantity || "";
            if (!quantity) {
                const extractedQuantity = selectedProduct.name.match(/(\d+)/);
                quantity = extractedQuantity ? extractedQuantity[1] : "";
            }
        }

        let priceWithRuble = selectedProduct.price;

        // Добавляем знак рубля через пробел, если его нет
        if (!priceWithRuble.includes(' ₽')) {
            priceWithRuble = `${priceWithRuble} ₽`;
        }

        // Если выбрали новый файл изображения, загружаем его в Cloudinary
        if (imageFile) {
            try {
                imageUrl = await uploadImageToCloudinary(imageFile);  // Дожидаемся завершения загрузки

                if (!imageUrl) {
                    toast.error('Ошибка загрузки изображения');
                    return;
                }
            } catch (error) {
                console.error('Ошибка загрузки изображения:', error);
                toast.error('Ошибка загрузки изображения');
                return;
            }
        }

        // Преобразуем данные перед отправкой
        const productToSave = {
            ...selectedProduct,
            image: imageUrl || selectedProduct.image,  // Если есть новое изображение, используем его
            game_id: parseInt(selectedProduct.game_id),
            quantity: selectedProduct.type === 'pack' ? quantity : "0",  // Преобразуем quantity в строку для типа pack
            days: selectedProduct.type === 'sub' ? days : 0,  // Преобразуем days в число для подписки
            price: priceWithRuble,
            type: selectedProduct.type === 'sub' ? 'sub' : 'pack',
        };

        try {
            const token = localStorage.getItem('token');
            if (!token) {
                toast.error('Пользователь не авторизован');
                return;
            }

            const response = await fetch(`https://gachashop-backend.onrender.com/products/update/${selectedProduct.id}`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${token}`, // Добавили токен
                },
                body: JSON.stringify({
                    ...productToSave,
                    _method: 'PUT',
                }),
            });

            if (response.ok) {
                toast.success('Товар успешно обновлен');
                const updatedProducts = await fetchProducts();
                setProducts(updatedProducts);
                setFilteredProducts(updatedProducts);
                setShowModal(false);
            } else {
                const result = await response.json();
                toast.error(result.error || 'Ошибка обновления товара');
            }
        } catch (error) {
            console.error('Ошибка обновления товара:', error);
            toast.error('Ошибка обновления товара');
        } finally {
            setIsLoading(false);
        }
    };

    const handleDeleteProduct = async (productId) => {
        const confirmation = window.confirm('Вы уверены, что хотите удалить этот товар?');
        if (confirmation) {
            const success = await deleteProduct(productId);
            if (success) {
                const updatedProducts = await fetchProducts();
                setProducts(updatedProducts);
                setFilteredProducts(updatedProducts);
            }
        }
    };

    const handleSearch = useCallback((e) => {
        const inputValue = typeof e === 'string' ? e : e.target.value;
        setSearchQuery(inputValue);

        let filtered = products;

        if (selectedGame) {
            filtered = filtered.filter((product) => product.game_id === parseInt(selectedGame));
        }

        if (selectedType) {
            filtered = filtered.filter((product) => product.type === (selectedType === 'Подписка' ? 'sub' : 'pack'));
        }

        const query = inputValue.toLowerCase().trim();
        if (query !== '') {
            filtered = filtered.filter((product) =>
                product.name.toLowerCase().includes(query)
            );
        }

        const sorted = sortProducts(filtered, sortOrder, selectedType);
        setFilteredProducts(sorted);
    }, [products, selectedGame, selectedType, sortOrder]);

    useEffect(() => {
        handleSearch(searchQuery);
    }, [selectedGame, selectedType, sortOrder, products, handleSearch, searchQuery]);

    return (
        <div>
            <div className="flex justify-between items-center mb-14 lg:px-2">
                <p className="pl-2 text-left font-bold text-2xl lg:text-3xl">Управление товарами</p>
                <button
                    onClick={handleAddProductClick}
                    className="bg-main-purple text-white text-sm mr-2 p-1 lg:p-2 border-2 border-main-purple rounded-xl hover:text-main-purple hover:bg-white ease-in-out duration-100"
                >
                    + Добавить товар
                </button>
            </div>

            <div className="flex flex-col lg:flex-row lg:justify-between mb-4 space-y-4 lg:space-y-0 lg:space-x-4 px-2 lg:px-4">
                {/* Фильтры */}
                <div className="flex flex-row lg:flex-grow xl:flex-grow-0 xl:w-[550px] justify-between lg:justify-normal flex-wrap lg:flex-nowrap gap-2">
                    <select
                        id="gameFilter"
                        value={selectedGame}
                        onChange={handleGameFilter}
                        className="text-black border-0 py-2 px-3 focus:ring-2 focus:ring-main-purple rounded-2xl w-44 lg:w-full"
                    >
                        <option value="">Все игры</option>
                        {games.map((game) => (
                            <option key={game.id} value={game.id}>
                                {game.name}
                            </option>
                        ))}
                    </select>

                    <select
                        id="typeFilter"
                        value={selectedType}
                        onChange={handleTypeFilter}
                        className="text-black border-0 py-2 px-3 focus:ring-2 focus:ring-main-purple rounded-2xl w-28 lg:w-full"
                    >
                        <option value="">Все типы</option>
                        <option value="Подписка">Подписка</option>
                        <option value="Пак">Пак</option>
                    </select>

                    <select
                        id="sortOrder"
                        value={sortOrder}
                        onChange={handleSortOrder}
                        className="text-black border-0 py-2 px-3 focus:ring-2 focus:ring-main-purple rounded-2xl w-44 lg:w-full"
                    >
                        <option value="">Без сортировки</option>
                        <option value="asc">По возрастанию</option>
                        <option value="desc">По убыванию</option>
                    </select>
                </div>

                {/* Поиск */}
                <div className="relative w-full lg:w-56 xl:w-72">
                    <Search className="absolute left-3 top-1/2 lg:top-5 transform -translate-y-1/2 text-gray-500" size={20} />
                    <input
                        type="text"
                        id="search"
                        value={searchQuery}
                        onChange={handleSearch}
                        className="text-black pl-10 py-2 w-full rounded-2xl border-0 focus:ring-2 focus:ring-main-purple"
                        placeholder="Поиск по названию..."
                    />
                </div>
            </div>


            <div className='px-4'>
                {filteredProducts.length === 0 ? (
                    <p className="text-center text-gray-500 flex justify-center items-center h-64 md:h-32">Товары по запросу не найдены</p>
                ) : (filteredProducts.map((product) => (
                    <div key={product.id} className="border p-4 mb-4 flex items-center">
                        <div className="flex-1 text-sm lg:text-base">
                            <p className="text-lg lg:text-xl font-bold">{product.name}</p>
                            <p className='text-sm lg:text-base pb-4'>{product.description}</p>
                            <p>Игра: {games.find((game) => game.id === product.game_id)?.name}</p>
                            <p>Цена: {product.price}</p>
                            {product.type === 'sub' && <p>Дней: {product.days}</p>}
                            {product.type === 'pack' && <p>Количество валюты: {product.quantity}</p>}

                            <div className='flex flex-row space-x-2'>
                                {/* Кнопка редактирования */}
                                <button
                                    onClick={() => handleEditProductClick(product)}  // редактирование
                                    className="bg-transparent border border-menu-purple text-menu-purple p-2 rounded-xl mt-2 hover:bg-menu-purple hover:text-black ease-in-out duration-100"
                                >
                                    Редактировать
                                </button>

                                <button
                                    onClick={() => handleDeleteProduct(product.id)}  // удаление
                                    className="bg-transparent border border-red-400 text-red-400 p-2 rounded-xl mt-2 hover:bg-red-400 hover:text-black ease-in-out duration-100"
                                >
                                    Удалить
                                </button>
                            </div>

                        </div>

                        {/* Добавляем картинку справа от карточки товара */}
                        {product.image && (
                            <div className="ml-4">
                                <img
                                    src={product.image}
                                    alt={product.name}
                                    className="w-28 lg:w-32 lg:h-32 object-cover rounded-md"
                                />
                            </div>
                        )}
                    </div>
                ))
                )}
            </div>

            {showModal && (
                <div
                    className="fixed inset-0 flex items-center justify-center bg-gray-500 bg-opacity-75"
                    onMouseDown={(e) => {
                        backdropClickRef.current = e.target === e.currentTarget;
                    }}
                    onMouseUp={(e) => {
                        if (backdropClickRef.current && e.target === e.currentTarget) {
                            setShowModal(false);
                        }
                    }}
                >
                    <div className="bg-hover-purple border p-6 rounded shadow-md">
                        <h3 className="text-2xl text-white mb-4">
                            {selectedProduct ? 'Редактировать товар' : 'Добавить товар'}
                        </h3>

                        <input
                            type="text"
                            name="name"
                            placeholder="Название товара"
                            value={modalMode === 'edit' ? selectedProduct.name : newProduct.name}
                            onChange={handleInputChange}
                            className="block text-black mb-2 p-2 border-0 w-full rounded-lg focus:ring-0"
                        />

                        <textarea
                            type="text"
                            name="description"
                            placeholder="Описание товара"
                            value={modalMode === 'edit' ? selectedProduct.description : newProduct.description}  // Зависит от режима
                            onChange={handleInputChange}
                            className="block text-black mb-2 p-2 border-0 w-full rounded-lg focus:ring-0"
                        />

                        {modalMode === 'edit' && selectedProduct.image ? (
                            <div className="flex flex-col items-center py-2">
                                <p className='text-lg'>Нажмите на изображение для изменения:</p>
                                <img
                                    src={selectedProduct.image}
                                    alt="Изображение товара"
                                    className="w-32 h-32 object-cover rounded-md mb-2 cursor-pointer"
                                    onClick={() => document.querySelector('input[name="image"]').click()} // Клик по изображению для замены
                                />
                            </div>
                        ) : (
                            <div className="flex flex-col py-2 space-y-1 justify-center">
                                <p className='text-lg'>Загрузка изображения для товара:</p>
                                <button
                                    onClick={() => document.querySelector('input[name="image"]').click()} // Кнопка для добавления изображения
                                    className="w-full h-20 bg-transparent border border-white text-white p-2 hover:bg-white hover:text-black ease-in-out duration-100"
                                >
                                    Загрузить изображение
                                </button>
                            </div>
                        )}

                        <input
                            type="file"
                            name="image"
                            accept="image/*"
                            onChange={handleFileChange}
                            className="block mb-2 p-2 border w-full"
                            style={{ display: 'none' }} // Скрываем поле ввода для файла
                        />

                        <select
                            name="game_id"
                            value={modalMode === 'edit' ? selectedProduct.game_id : newProduct.game_id}
                            onChange={handleInputChange}
                            className="block mt-4 mb-2 p-2 w-full text-black border-0 py-2 focus:ring-2 focus:ring-main-purple rounded-2xl"
                        >
                            <option value="">Выберите игру</option>
                            {games.map((game) => (
                                <option key={game.id} value={game.id}>
                                    {game.name}
                                </option>
                            ))}
                        </select>

                        <input
                            type="text"
                            name="price"
                            placeholder="Цена товара (число)"
                            value={modalMode === 'edit' ? selectedProduct.price : newProduct.price}
                            onChange={handleInputChange}
                            className="block text-black mb-2 p-2 border-0 w-full rounded-lg focus:ring-0"
                        />

                        <select
                            name="type"
                            value={modalMode === 'edit' ? selectedProduct.type : newProduct.type}  // Теперь по умолчанию 'sub' корректно применяется для нового товара
                            onChange={handleInputChange}
                            className="block mb-2 p-2 w-full text-black border-0 py-2 focus:ring-2 focus:ring-main-purple rounded-2xl"
                        >
                            <option value="sub">Подписка</option>
                            <option value="pack">Пак</option>
                        </select>

                        {(modalMode === 'edit' ? (selectedProduct.type === 'pack') : (newProduct.type === 'pack')) && (
                            <input
                                type="text"
                                name="quantity"
                                placeholder="Количество валюты"
                                value={modalMode === 'edit' ? selectedProduct.quantity : newProduct.quantity}
                                onChange={handleInputChange}
                                className="block text-black mb-2 p-2 border-0 w-full rounded-lg focus:ring-0"
                            />
                        )}

                        {(modalMode === 'edit' ? (selectedProduct.type === 'sub') : (newProduct.type === 'sub')) && (
                            <input
                                type="number"
                                name="days"
                                placeholder="Количество дней"
                                value={modalMode === 'edit' ? selectedProduct.days : newProduct.days}
                                onChange={handleInputChange}
                                className="block text-black mb-2 p-2 border-0 w-full rounded-lg focus:ring-0"
                            />
                        )}

                        <div className="flex justify-end">
                            <button
                                onClick={() => setShowModal(false)}
                                className="bg-gray-300 border border-gray-300 text-black rounded p-2 mr-2 hover:opacity-75 ease-in-out duration-100"
                                disabled={isLoading}  // Блокируем кнопку "Отмена" при загрузке
                            >
                                Отмена
                            </button>
                            <button
                                onClick={modalMode === 'edit' ? handleEditProduct : handleAddProduct}
                                className={`p-2 text-black border border-menu-purple rounded ${isLoading ? 'bg-gray-500' : 'bg-menu-purple hover:opacity-75 ease-in-out duration-100'}`}
                                disabled={isLoading}  // Блокируем кнопку во время загрузки
                            >
                                {isLoading ? 'Загрузка...' : (modalMode === 'edit' ? 'Сохранить' : 'Добавить')}
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );

}

export default ProductManagement;
