import { Link } from 'react-router-dom';
import tg from "./images/Socials/telegram.png";
import vk from "./images/Socials/vk.png";

function Footer() {
    return (
        <div className="w-full border-t-[0.5px] mt-4">
            <div className="container h-[210px] mx-auto p-4 flex justify-between">
                <div className="ml-5 w-60 text-[#FFFFFF] text-[12px] flex flex-col">
                    <p>
                        Все права принадлежат их правообладателям / All rights belong to their copyright holders.
                        <br></br>
                        <br></br>
                        Сайт не аффилирован и не одобрен компанией разработчиком игры Genshin Impact / The site is not affiliated with or approved by the game developer Genshin Impact.
                    </p>
                    
                    <p className="mt-[10px]">
                        GachaShop (GS) {new Date().getFullYear()}
                    </p>
                </div>

                <div className='flex flex-col'>
                   <Link to="https://web.telegram.org/a/" target='_blank' title="Наш тг канал!" className='ease-in-out duration-200 hover:scale-125' >
                   <img src={tg} alt="ТГк" className='w-[27px]'/>
                   </Link>

                   <Link to="https://vk.com" target='_blank' title="Наша группа вк!" className='ease-in-out duration-200 hover:scale-125' >
                   <img src={vk} alt="ВК" className='w-[27px] mt-[10px]' />
                   </Link> 
                </div>
            </div>
        </div>
    );
}



export default Footer;