import React from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { useState, useEffect, useCallback } from 'react';
import Header from "../components/Header";
import Footer from "../components/Footer";
import { IMaskInput } from 'react-imask';
import { toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import { useUserContext } from "../components/Context";

import back from "../components/images/Register_and_Auth/back-button.png";
import card from "../components/images/Payment_methods/approve.png";
import cardHover from "../components/images/Payment_methods/approve (purple).png";
import cashback from "../components/images/Payment_methods/blockchain.png";
import cashbackHover from "../components/images/Payment_methods/blockchain(purple).png";

import { FaCheck } from 'react-icons/fa';

const luhnCheck = (number) => {
    let sum = 0;
    let shouldDouble = false;

    // Прочитываем номер карты с конца
    for (let i = number.length - 1; i >= 0; i--) {
        let digit = parseInt(number.charAt(i), 10);

        if (shouldDouble) {
            digit *= 2;
            if (digit > 9) digit -= 9;  // Суммируем цифры, если результат больше 9
        }

        sum += digit;
        shouldDouble = !shouldDouble;
    }

    // Номер карты проходит валидацию, если сумма кратна 10
    return sum % 10 === 0;
};

// Валидация префикса для карт Visa, Mastercard и МИР
const validateCardPrefix = (cardNumber) => {
    const visaPrefix = /^4/;
    const mastercardPrefix = /^(51|52|53|54|55)/;
    const mirPrefix = /^2200/;

    return visaPrefix.test(cardNumber) || mastercardPrefix.test(cardNumber) || mirPrefix.test(cardNumber);
};

const validateCardDate = (cardDate) => {
    const currentYear = new Date().getFullYear(); // Текущий год
    const currentMonth = new Date().getMonth() + 1; // Месяцы от 0 до 11, поэтому добавляем 1

    // Разделяем строку на месяц и год
    const [month, year] = cardDate.split('/');

    // Проверка на правильный формат
    if (!month || !year || month.length !== 2 || year.length !== 2) {
        return 'Неверный формат. Используйте MM/YY.';
    }

    // Проверка на корректность месяца
    const monthInt = parseInt(month, 10);
    if (monthInt < 1 || monthInt > 12) {
        return 'Месяц должен быть от 01 до 12.';
    }

    // Проверка на корректность года
    const yearInt = parseInt(year, 10);
    if (yearInt < currentYear % 100) {
        return 'Срок действия карты истек.';
    }

    // Если год текущий, проверяем, чтобы месяц не был в прошлом
    if (yearInt === currentYear % 100 && monthInt < currentMonth) {
        return 'Срок действия карты истек.';
    }

    return ''; // Всё ок
};

function CheckoutPage() {
    const location = useLocation();
    const [product, setProduct] = useState(null);
    const { user } = useUserContext();
    const navigate = useNavigate();

    useEffect(() => {
        if (!user) {
            // Если пользователь не авторизован, перенаправляем на главную страницу
            navigate('/');
        }
    }, [user, navigate]);

    const [isFirstOrder, setIsFirstOrder] = useState(false); // Это первый заказ?
    const [cashbackPercentage, setCashbackPercentage] = useState(5);
    const [cashbackAmount, setCashbackAmount] = useState(0);

    const [paymentMethod, setPaymentMethod] = useState('card');
    const [userCashback, setUserCashback] = useState(0);

    const [savedCards, setSavedCards] = useState([]);
    const [selectedCard, setSelectedCard] = useState(null);

    useEffect(() => {
        const fetchUserCashback = async () => {
            const token = localStorage.getItem('token');
            if (!token) return;

            try {
                const response = await fetch(`https://gachashop-backend.onrender.com/user/get-user-cashback`, {
                    method: 'GET',
                    headers: {
                        'Content-Type': 'application/json',
                        'Authorization': `Bearer ${token}`,
                    },
                });

                if (response.ok) {
                    const data = await response.json();
                    setUserCashback(data.user_cashback);
                } else {
                    console.error("Ошибка при получении кэшбека пользователя");
                }
            } catch (error) {
                console.error("Ошибка при запросе кэшбека пользователя:", error);
            }
        };

        if (user) fetchUserCashback();
    }, [user]);

    useEffect(() => {
        const fetchCards = async () => {
            const token = localStorage.getItem('token');
            if (!token) {
                console.warn("Токен не найден, пропускаем запрос карт");
                return;
            }

            try {
                const response = await fetch(`https://gachashop-backend.onrender.com/card/get-user-cards`, {
                    method: 'GET',
                    headers: {
                        'Authorization': `Bearer ${token}`,
                        'Content-Type': 'application/json',
                    },
                });

                if (!response.ok) {
                    throw new Error("Ошибка при загрузке карт");
                }

                const data = await response.json();
                setSavedCards(data.cards);
            } catch (error) {
                console.error("Ошибка при загрузке карт:", error);
            }
        };

        if (user) fetchCards();
    }, [user]);

    const fetchOrderCount = useCallback(async () => {
        const token = localStorage.getItem('token');
        if (!token) {
            console.warn("Токен не найден, пропускаем запрос количества заказов");
            return;
        }

        try {
            const response = await fetch(`https://gachashop-backend.onrender.com/order/count`, {
                method: 'GET',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${token}`,
                },
            });

            if (response.ok) {
                const data = await response.json();
                setIsFirstOrder(data.count === 0);
                setCashbackPercentage(data.count === 0 ? 7 : 5);
                setSelectedCard(data.count === 0 ? "new" : "");
            } else {
                console.error("Ошибка при получении количества заказов");
            }
        } catch (error) {
            console.error("Ошибка при запросе количества заказов:", error);
        }
    }, []);

    useEffect(() => {
        if (user) {
            fetchOrderCount(); // Получаем количество заказов пользователя
        }
    }, [user, fetchOrderCount]);

    const [cardName, setCardName] = useState('');
    const [cardNumber, setCardNumber] = useState('');
    const [cardDate, setCardDate] = useState('');
    const [cardCVC, setCardCVC] = useState('');
    const [saveCard, setSaveCard] = useState(false);

    const [cardNameError, setCardNameError] = useState('');
    const [cardNumberError, setCardNumberError] = useState('');
    const [cardDateError, setCardDateError] = useState('');
    const [cardCVCError, setCardCVCError] = useState('');

    const handleCardNumberChange = (e) => {
        const number = e.target.value.replace(/\s+/g, ''); // Убираем пробелы из номера
        setCardNumber(number);

        // Валидация номера карты
        if (!number) {
            setCardNumberError('Номер карты не может быть пустым');
        } else if (!luhnCheck(number)) {
            setCardNumberError('Неверный номер карты');
        } else if (!validateCardPrefix(number)) {
            setCardNumberError('Номер карты не соответствует поддерживаемым картам (МИР, Visa, Mastercard)');
        } else {
            setCardNumberError(''); // Если ошибок нет, очищаем ошибку
        }
    };

    const handleCardDateChange = (e) => {
        const date = e.target.value;
        setCardDate(date);

        // Валидация срока действия карты
        const error = validateCardDate(date);
        setCardDateError(error);
    };

    const handleCardNameChange = (e) => {
        const name = e.target.value;
        setCardName(name);
        setCardNameError(name.trim() === '' ? 'Поле имени на карте обязательно для ввода' : '');
    };

    const handleCardCVCChange = (e) => {
        const cvc = e.target.value;
        setCardCVC(cvc);
        setCardCVCError(cvc.length !== 3 ? 'CVV / CVC должен быть из 3 цифр' : '');
    };

    useEffect(() => {
        const params = new URLSearchParams(location.search);

        const productFromState = location.state;

        if (productFromState) {
            setProduct(productFromState);
        } else {
            const productData = {
                name: params.get('name'),
                image: params.get('image'),
                price: params.get('price'),
                id: params.get('id')
            };

            if (productData.name && productData.image && productData.price && productData.id) {
                setProduct(productData);
            } else {
                console.error('Не найдены данные о товаре');
            }
        }
    }, [location]);

    const parsePrice = (priceString) => {
        // Убираем знак валюты и пробелы
        return parseFloat(priceString.replace(/[^\d.-]/g, ''));
    };

    const calculateCashback = useCallback((price) => {
        const priceNumber = parsePrice(price);
        const cashback = Math.round((priceNumber * cashbackPercentage) / 100);
        setCashbackAmount(cashback);
    }, [cashbackPercentage]);

    useEffect(() => {
        if (product && cashbackPercentage) {
            calculateCashback(product.price); // Рассчитываем кэшбэк на основе цены
        }
    }, [product, cashbackPercentage, calculateCashback]);

    const handleBackClick = () => {
        navigate(`/product/${product.id}`);
    };

    const handleSubmit = async (e) => {
        e.preventDefault();

        setCardNameError('');
        setCardNumberError('');
        setCardDateError('');
        setCardCVCError('');

        const errors = [];

        if (paymentMethod === 'card' && selectedCard === 'new') {
            // Валидация имени карты
            if (!cardName) {
                setCardNameError('Имя на карте обязательно');
                errors.push('Имя на карте обязательно');
            }

            // Валидация номера карты
            if (!cardNumber) {
                setCardNumberError('Номер карты не может быть пустым');
                errors.push('Номер карты не может быть пустым');
            } else if (!luhnCheck(cardNumber)) {
                setCardNumberError('Неверный номер карты');
                errors.push('Неверный номер карты');
            } else if (!validateCardPrefix(cardNumber)) {
                setCardNumberError('Номер карты не соответствует поддерживаемым картам (МИР, Visa, Mastercard)');
                errors.push('Номер карты не соответствует поддерживаемым картам (МИР, Visa, Mastercard)');
            }

            // Валидация срока действия карты
            if (!cardDate) {
                setCardDateError('Срок действия карты обязателен');
                errors.push('Срок действия карты обязателен');
            } else {
                const dateError = validateCardDate(cardDate); // Проверка на корректность срока действия
                if (dateError) {
                    setCardDateError(dateError);
                    errors.push(dateError);
                }
            }

            // Валидация CVV/CVC
            if (!cardCVC) {
                setCardCVCError('CVV/CVC код обязателен');
                errors.push('CVV/CVC код обязателен');
            } else if (cardCVC.length !== 3) {
                setCardCVCError('CVV / CVC должен быть из 3 цифр');
                errors.push('CVV / CVC должен быть из 3 цифр');
            }
        } else if (paymentMethod === 'card' && selectedCard !== 'new') {
            // Валидация для сохранённой карты: проверяем только, что выбрана карта
            if (!selectedCard || selectedCard === 'new') {
                errors.push('Не выбрана сохранённая карта');
            }
        }

        // Проверки для способа оплаты через кэшбек
        if (paymentMethod === 'cashback') {
            // Проверка на достаточность баллов кэшбека
            if (userCashback < parsePrice(product.price)) {
                errors.push('Недостаточно баллов кэшбека для оплаты');
            }
        }

        // Если ошибки есть, останавливаем отправку формы
        if (errors.length > 0) {
            return;
        } else {
            // Логика для карты
            if (paymentMethod === 'card') {
                let cardData = {};

                if (selectedCard === 'new') {
                    // Отправляем данные для новой карты
                    cardData = {
                        card_name: cardName,
                        card_number: cardNumber.replace(/\s+/g, ''), // Убираем пробелы из номера карты
                        card_date: cardDate,
                        save_card: saveCard,
                    };
                } else {
                    // Отправляем только идентификатор карты для сохраненной карты
                    cardData = {
                        cardNumber: savedCards,
                    };
                }

                try {
                    // Сначала сохраняем или обновляем данные карты
                    const token = localStorage.getItem('token');

                    const response = await fetch('https://gachashop-backend.onrender.com/card/save', {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                            'Authorization': `Bearer ${token}`,  // передаем токен сюда
                        },
                        body: JSON.stringify(cardData),
                    });


                    if (response.ok) {
                        const orderData = {
                            order_name: product.name,
                            order_date: new Date().toISOString(),
                            order_price: `${parsePrice(product.price)}`,
                            order_cashback: cashbackAmount,
                            order_status: 3,
                            order_method: paymentMethod,
                        };

                        if (selectedCard === 'new') {
                            // Если карта новая, маскируем номер
                            const maskedCardNumber = `**** ${cardNumber.slice(-4)}`; // Маскируем, оставляем последние 4 цифры
                            orderData.card_number = maskedCardNumber;
                        } else {
                            // Если выбрана сохраненная карта, отправляем маскированный номер
                            orderData.card_number = `**** ${savedCards.find(card => card.id === Number(selectedCard)).lastFour}`;
                        }

                        const orderResponse = await fetch('https://gachashop-backend.onrender.com/order/create', {
                            method: 'POST',
                            headers: {
                                'Content-Type': 'application/json',
                                'Authorization': `Bearer ${token}`,
                            },
                            body: JSON.stringify(orderData)
                        });

                        if (orderResponse.ok) {
                            const orderData = await orderResponse.json();

                            if (orderData.success) {
                                // Переход на страницу успеха с кодом
                                window.location.href = `/#/success?code=${orderData.order_code}`;
                            } else {
                                toast.error('Ошибка при создании заказа');
                            }
                        } else {
                            toast.error('Ошибка при создании заказа');
                        }
                    } else {
                        console.error("Ошибка при оплате заказа");
                    }
                } catch (error) {
                    console.error("Ошибка при отправке данных:", error);
                }
            }
            // Логика для кэшбека
            else if (paymentMethod === 'cashback') {
                // Оплата через кэшбэк
                const orderData = {
                    user_id: user.id,
                    order_name: product.name,
                    order_date: new Date().toISOString(),
                    order_price: `${parsePrice(product.price)}`,
                    order_cashback: cashbackAmount,
                    order_status: 3,
                    order_method: paymentMethod,
                };

                try {
                    const token = localStorage.getItem('token');

                    const orderResponse = await fetch('https://gachashop-backend.onrender.com/order/create', {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                            'Authorization': `Bearer ${token}`,
                        },
                        body: JSON.stringify(orderData)
                    });

                    if (orderResponse.ok) {
                        // Обновляем баллы кэшбека
                        const userResponse = await fetch('https://gachashop-backend.onrender.com/user/update-cashback', {
                            method: 'POST',
                            headers: {
                                'Content-Type': 'application/json',
                                'Authorization': `Bearer ${token}`,
                            },
                            body: JSON.stringify({
                                user_id: user.id,
                                cashback_amount: -parsePrice(product.price), // Вычитаем сумму кэшбека
                            }),
                        });

                        if (userResponse.ok) {
                            toast.success('Ваш заказ успешно оформлен!');
                        } else {
                            toast.error('Ошибка при обновлении кэшбека пользователя');
                        }

                        const orderData = await orderResponse.json();

                        if (orderData.success) {
                            // Переход на страницу успеха с кодом
                            window.location.href = `/#/success?code=${orderData.order_code}`;
                        } else {
                            toast.error('Ошибка при создании заказа');
                        }
                    } else {
                        toast.error('Ошибка при создании заказа');
                    }
                } catch (error) {
                    console.error("Ошибка при отправке данных:", error);
                }
            }
        }
    };

    return (
        <div className="bg-[#000000] font-seravek min-h-screen flex flex-col">
            <div className='w-full'>
                <Header />
                {/* Кнопка назад */}
                <div className="container mx-auto px-6 md:px-11 my-[30px]">
                    <button onClick={handleBackClick} className="flex justify-start items-center space-x-[10px]">
                        <img src={back} alt="Стрелка назад" className="w-5 xl:w-6" />
                        <span className="text-base xl:text-xl text-[#FFFFFF]">К товару</span>
                    </button>
                </div>
            </div>
            <div className="flex flex-col flex-grow">
                {product ? (
                    <div className="container flex flex-col justify-center items-center mx-auto mb-[20px]">
                        <div className='flex flex-col w-full lg:w-auto space-y-5 md:px-11'>
                            {/* Заголовок */}
                            <div>
                                <h2 className='text-white text-3xl xl:text-4xl'>Оплата</h2>
                            </div>

                            <div className='flex flex-col-reverse lg:flex-row flex-grow lg:space-x-[75px] lg:justify-center'>
                                <div className='flex flex-col space-y-6 lg:w-[600px]'>

                                    {/* Способы оплаты */}
                                    <div className='space-y-4'>
                                        <h2 className='text-white text-lg xl:text-2xl border-b'>Способы оплаты</h2>

                                        <div className="flex flex-col space-y-4 px-2 lg:px-0">
                                            {/* Радиокнопка "Банковская карта" */}
                                            <label className={`flex justify-center lg:justify-start items-center gap-4 cursor-pointer ${paymentMethod === 'card' ? 'border lg:border-0 border-[#976BD6] p-2 lg:p-0 rounded-xl lg:rounded-none' : 'border-0'}`}>
                                                <input
                                                    type="radio"
                                                    id="card"
                                                    name="paymentMethod"
                                                    value="card"
                                                    checked={paymentMethod === "card"}
                                                    onChange={() => {
                                                        setPaymentMethod("card");
                                                    }}
                                                    className="hidden peer"
                                                />
                                                {/* Кастомная радиокнопка */}
                                                <div className="hidden w-6 h-6 opacity-50 rounded-full border-2 border-gray-300 peer-checked:opacity-100 peer-checked:border-[#976BD6] peer-checked:bg-[#976BD6] lg:flex items-center justify-center ease-in-out duration-200"></div>

                                                <img src={paymentMethod === "card" ? cardHover : card} alt="card"
                                                    className={paymentMethod === "card" ? `w-8` : `w-8 opacity-50`} />

                                                <span className="opacity-50 text-white text-base xl:text-xl peer-checked:text-[#976BD6] peer-checked:opacity-100 ease-in-out duration-200">Банковская карта</span>
                                            </label>

                                            {/* Радиокнопка "Кэшбек" */}
                                            <label className={`flex justify-center lg:justify-start items-center gap-4 cursor-pointer ${paymentMethod === 'cashback' ? 'border lg:border-0 border-[#976BD6] p-2 lg:p-0 rounded-xl lg:rounded-none' : 'border-0'}`}>
                                                <input
                                                    type="radio"
                                                    id="cashback"
                                                    name="paymentMethod"
                                                    value="cashback"
                                                    checked={paymentMethod === "cashback"}
                                                    onChange={() => {
                                                        setPaymentMethod("cashback");
                                                    }}
                                                    className="hidden peer"
                                                />
                                                {/* Кастомная радиокнопка */}
                                                <div className="hidden w-6 h-6 opacity-50 rounded-full border-2 border-gray-300 peer-checked:opacity-100 peer-checked:border-[#976BD6] peer-checked:bg-[#976BD6] lg:flex items-center justify-center ease-in-out duration-200"></div>

                                                <img src={paymentMethod === "cashback" ? cashbackHover : cashback} alt="cashback"
                                                    className={paymentMethod === "cashback" ? `w-8` : `w-8 opacity-50`} />

                                                <span className="text-white text-base xl:text-xl opacity-50 peer-checked:text-[#976BD6] peer-checked:opacity-100 ease-in-out duration-200">Баллы кэшбека</span>
                                            </label>
                                        </div>
                                    </div>

                                    {/* Форма оплаты картой */}
                                    {paymentMethod === 'card' && (
                                        <div className="space-y-[15px]">
                                            {/* Выбор карты */}
                                            <div className="flex flex-col lg:flex-row justify-start lg:justify-between lg:items-center px-2 lg:px-0">
                                                <label className="text-white text-lg xl:text-xl">Выберите банковскую карту:</label>
                                                <select
                                                    id="card"
                                                    name="paymentMethod"
                                                    value={selectedCard}
                                                    onChange={(e) => {
                                                        setSelectedCard(e.target.value);
                                                    }}
                                                    className="text-black lg:w-[220px] p-2 rounded-md bg-[#ddd9d9] focus:ring-0 focus:ring-offset-0"
                                                >
                                                    <option value="">Выбрать</option>
                                                    {savedCards.map((card) => (
                                                        <option key={card.id} value={card.id}>
                                                            {card.cardType} **** {card.lastFour}
                                                        </option>
                                                    ))}
                                                    <option value="new">Добавить новую карту</option>
                                                </select>
                                            </div>

                                            {/* Форма для добавления новой карты */}
                                            {selectedCard === 'new' && (
                                                <div className='space-y-[15px]'>
                                                    <p className='text-white text-lg xl:text-2xl border-b'>Детали оплаты</p>
                                                    <form className='flex flex-col items-center space-y-2 px-2 lg:px-0' onSubmit={handleSubmit}>
                                                        <div className='w-full space-y-[5px]'>
                                                            <label className='text-base xl:text-lg text-white'>Имя на карте</label>
                                                            <input
                                                                type="text"
                                                                className="w-full bg-[#ddd9d9] rounded-md focus:outline-none focus:ring-0"
                                                                value={cardName}
                                                                onChange={handleCardNameChange}
                                                            />
                                                            {cardNameError && <p className="text-red-500 text-sm">{cardNameError}</p>}
                                                        </div>

                                                        <div className='w-full space-y-[5px]'>
                                                            <label className='text-base xl:text-lg text-white'>Номер карты (Visa, Mastercard, МИР)</label>
                                                            <IMaskInput
                                                                mask="0000 0000 0000 0000"
                                                                value={cardNumber}
                                                                onAccept={(value) => setCardNumber(value)}
                                                                className="w-full bg-[#ddd9d9] rounded-md focus:outline-none focus:ring-0"
                                                                placeholder="0000 0000 0000 0000"
                                                                onChange={handleCardNumberChange}
                                                            />
                                                            {cardNumberError && <p className="text-red-500 text-sm">{cardNumberError}</p>}
                                                        </div>

                                                        <div className='flex space-x-[20px]'>
                                                            <div>
                                                                <label className='text-base xl:text-lg text-white'>Срок действия</label>
                                                                <IMaskInput
                                                                    mask="00/00"
                                                                    value={cardDate}
                                                                    onAccept={(value) => setCardDate(value)}
                                                                    className="w-full bg-[#ddd9d9] rounded-md focus:outline-none focus:ring-0"
                                                                    placeholder="MM/YY"
                                                                    onChange={handleCardDateChange}
                                                                />
                                                                {cardDateError && <p className="text-red-500 text-sm">{cardDateError}</p>}
                                                            </div>

                                                            <div>
                                                                <label className='text-base xl:text-lg text-white'>CVV / CVC код</label>
                                                                <IMaskInput
                                                                    mask="000"
                                                                    value={cardCVC}
                                                                    onAccept={(value) => setCardCVC(value)}
                                                                    className="w-full bg-[#ddd9d9] rounded-md focus:outline-none focus:ring-0"
                                                                    placeholder="000"
                                                                    onChange={handleCardCVCChange}
                                                                />
                                                                {cardCVCError && <p className="text-red-500 text-sm">{cardCVCError}</p>}
                                                            </div>
                                                        </div>

                                                        <div className='w-full flex items-center mt-4'>
                                                            <input
                                                                type="checkbox"
                                                                id="saveCard"
                                                                checked={saveCard}
                                                                onChange={(e) => setSaveCard(e.target.checked)}
                                                                className="mr-2 text-[#976BD6] bg-[#ddd9d9] focus:ring-0 focus:ring-offset-0"
                                                            />
                                                            <label htmlFor="saveCard" className='text-sm lg:text-md xl:text-lg text-white'>
                                                                Сохранить карту для будущих платежей
                                                            </label>
                                                        </div>

                                                        <button
                                                            type="submit"
                                                            className="w-full py-2 lg:py-3 mt-6 bg-[#976BD6] text-black text-lg xl:text-xl rounded-md hover:bg-[#684a91] ease-in-out duration-200"
                                                        >
                                                            Оплатить ({product.price})
                                                        </button>
                                                    </form>
                                                </div>
                                            )}

                                            {/* Детали оплаты с выбранной картой */}
                                            {selectedCard !== 'new' && selectedCard && (
                                                <div className='space-y-[15px]'>
                                                    <p className='text-white text-lg xl:text-2xl border-b'>Детали оплаты</p>
                                                    {savedCards.find(card => card.id === Number(selectedCard)) ? (
                                                        <form onSubmit={handleSubmit} className='px-2 lg:px-0'>
                                                            <div className='flex flex-grow space-x-[5px] items-center'>
                                                                <FaCheck className="text-[#976BD6] h-4 xl:h-6 w-4 xl:w-6" />
                                                                <p className="text-white text-base xl:text-lg">
                                                                    {savedCards.find(card => card.id === Number(selectedCard)).cardType} **** {savedCards.find(card => card.id === Number(selectedCard)).lastFour}
                                                                </p>
                                                            </div>

                                                            <button
                                                                type="submit"
                                                                className="w-full py-2 lg:py-3 mt-6 bg-[#976BD6] text-black text-lg xl:text-xl rounded-md hover:bg-[#684a91] ease-in-out duration-200"
                                                            >
                                                                Оплатить ({product.price})
                                                            </button>
                                                        </form>
                                                    ) : (
                                                        <p className="text-white">Выбранная карта не найдена</p>
                                                    )}
                                                </div>
                                            )}
                                        </div>
                                    )}

                                    {/* Форма оплаты кэшбеком */}
                                    {paymentMethod === 'cashback' && (
                                        <div className="flex flex-col space-y-3 w-full">
                                            <p className="text-white text-lg xl:text-2xl border-b">Детали оплаты</p>
                                            <form onSubmit={handleSubmit} className="space-y-3 px-2 lg:px-0">
                                                <p className="text-white text-base xl:text-lg">У вас доступно {userCashback} баллов кэшбека.</p>
                                                <p className="text-white text-base xl:text-lg">Для оплаты покупки необходимо {parsePrice(product.price)} баллов.</p>

                                                {/* Кнопка оплаты, если достаточно баллов */}
                                                <button
                                                    type="submit"
                                                    disabled={userCashback < parsePrice(product.price)} // Делаем кнопку неактивной, если недостаточно баллов
                                                    className={`w-full py-2 xl:py-3 mt-6 text-lg xl:text-xl ${userCashback < parsePrice(product.price) ? 'bg-gray-400 cursor-not-allowed' : 'bg-[#976BD6] hover:bg-[#684a91]'} text-black rounded-md ease-in-out duration-200`}
                                                >
                                                    Оплатить баллами ({product.price})
                                                </button>
                                            </form>
                                        </div>
                                    )}

                                </div>

                                <div className='lg:w-1/2 xl:w-[550px] space-y-4 xl:space-y-[20px] mb-4 lg:mb-0'>

                                    {/* Детали заказа */}
                                    <div className='space-y-3 xl:space-y-4'>
                                        <h2 className='text-white text-lg xl:text-2xl border-b'>Детали заказа</h2>
                                        <div className='flex items-center space-x-3 px-2 lg:px-0'>
                                            <img src={product.image} alt="goods" className='w-10 lg:w-14 xl:w-20' />
                                            <div className='flex flex-grow justify-between items-center'>
                                                <p className='text-base xl:text-xl text-white'>{product.name}</p>
                                                <p className='text-base xl:text-xl text-white'>1 шт.</p>
                                            </div>
                                        </div>
                                    </div>

                                    <div className='space-y-3 lg:space-y-4 flex flex-col'>
                                        <h2 className='text-white text-lg xl:text-2xl border-b'>Итоговые отчисления</h2>

                                        {/* Сумма заказа */}
                                        <div className='flex items-center space-x-[10px] px-2 lg:px-0'>
                                            <div className='flex flex-grow justify-between'>
                                                <p className='text-base xl:text-xl text-white'>Сумма к оплате:</p>
                                                <p className='text-base xl:text-xl text-white'>{product.price}</p>
                                            </div>
                                        </div>

                                        {paymentMethod === "card" && (
                                            <div className='space-y-[15px] flex flex-col px-2 lg:px-0'>
                                                {/* Процент кэшбека */}
                                                <div className='flex items-center space-x-[10px]'>
                                                    <div className='flex flex-grow justify-between'>
                                                        <p className='text-base xl:text-xl text-white'>Процент кэшбека:</p>
                                                        <p className='text-base xl:text-xl text-white'>
                                                            {isFirstOrder ? '7% (первый заказ)' : '5%'}
                                                        </p>
                                                    </div>
                                                </div>

                                                {/* Сумма кэшбека */}
                                                <div className='flex items-center space-x-[10px]'>
                                                    <div className='flex flex-grow justify-between'>
                                                        <p className='text-base xl:text-xl text-white'>Будет начислено кэшбека:</p>
                                                        <p className='text-base xl:text-xl text-white'>
                                                            {cashbackAmount} баллов
                                                        </p>
                                                    </div>
                                                </div>
                                            </div>
                                        )}

                                        {paymentMethod === "cashback" && (
                                            <div className='space-y-[15px] flex flex-col px-2 lg:px-0'>
                                                {/* Сумма кэшбека */}
                                                <div className='flex items-center space-x-[10px]'>
                                                    <div className='flex flex-grow justify-between'>
                                                        <p className='text-base xl:text-xl text-white'>Будет списано кэшбека:</p>
                                                        <p className='text-base xl:text-xl text-white'>
                                                            {product.price.slice(0, 3)} баллов
                                                        </p>
                                                    </div>
                                                </div>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            </div>

                        </div>
                    </div>
                ) : (<div className="text-white">Ошибка: данные о товаре не найдены. Пожалуйста, вернитесь назад и попробуйте снова.</div>
                )}
            </div>
            <Footer />
        </div>
    );
}

export default CheckoutPage;
