import React, { useEffect, useState, useContext } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import Header from "../components/Header";
import Footer from "../components/Footer";

import back from "../components/images/Register_and_Auth/back-button.png";
import hacker from "../components/images/Guarantees/backend.png";
import block from "../components/images/Guarantees/broken.png";
import cashback from "../components/images/Guarantees/security.png";

import { toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import { UserContext } from "../components/Context";

function ProductPage() {
    const { productId } = useParams(); // Получаем id товара из URL
    const [product, setProduct] = useState(null);
    const { user } = useContext(UserContext);
    const navigate = useNavigate();

    useEffect(() => {
        const fetchProduct = async () => {
            try {
                const productData = await fetch(`https://gachashop-backend.onrender.com/products/${productId}`).then(res => res.json());
                setProduct(productData);
            } catch (error) {
                console.error('Ошибка при загрузке данных о товаре:', error);
            }
        };

        fetchProduct();
    }, [productId]);

    const handleBuyClick = () => {
        if (!user) {
            toast.info('Для продолжения необходимо авторизоваться');
            const redirectTo = `/checkout?name=${encodeURIComponent(product.name)}&image=${encodeURIComponent(product.image)}&price=${encodeURIComponent(product.price)}&id=${product.id}`;
            navigate(`/auth?form=login&redirectTo=${encodeURIComponent(redirectTo)}`);
        } else {
            // Передаем данные через `state`
            const productData = {
                name: product.name,
                image: product.image,
                price: product.price,
                id: product.id
            };
            navigate("/checkout", { state: productData });
        }
    };

    if (!product) {
        return <div>Loading...</div>; // Показать индикатор загрузки, пока данные загружаются
    }

    return (
        <div className="bg-[#000000] font-seravek min-h-screen flex flex-col">
            <div className='w-full'>
                <Header />
                {/* Кнопка назад */}
                <div className="container mx-auto px-6 md:px-11 mt-[30px]">
                    <Link to="/catalog" className="flex flex-row justify-start items-center space-x-1 md:space-x-3">
                        <img src={back} alt="Стрелка назад" className="w-3 md:w-5 lg:w-5 xl:w-6" />
                        <span className="text-sm md:text-base xl:text-lg text-[#FFFFFF]">Вернуться в магазин</span>
                    </Link>
                </div>
            </div>
            <div className="flex flex-col flex-grow">
                <div className="container flex flex-grow flex-col mx-auto">
                    <div className='flex flex-grow justify-center'>
                        <div className="flex flex-col px-4 lg:px-0 lg:flex-row justify-center space-y-10 lg:space-y-0 lg:justify-between items-center">
                            {/* Скрытая картинка и заголовок для мобилок */}
                            <div className="flex lg:hidden justify-center items-center text-white">
                                <div className='flex flex-row items-center gap-4'>
                                    <img src={product.image} alt={product.name} className={`${product.type === "sub" ? 'w-36 md:w-56' : 'w-36 md:w-56'}`} />
                                    <div className='flex flex-col'>
                                        <h1 className="text-lg md:text-xl font-bold mb-2 md:mb-5">{product.name}</h1>
                                        <p className=' text-sm md:text-base mb-4'>{product.description}</p>
                                        <button
                                            onClick={handleBuyClick}
                                            className="py-2 bg-[#976BD6] text-black text-sm md:text-base rounded-md hover:bg-[#684a91] ease-in-out duration-200"
                                        >
                                            Купить сейчас ({product.price})
                                        </button>
                                    </div>
                                </div>
                            </div>

                            {/* Левая часть */}
                            <div className="hidden lg:flex flex-col lg:w-80 xl:w-96 text-white">
                                <h1 className="hidden lg:block lg:text-2xl xl:text-4xl font-bold mb-5">{product.name}</h1>
                                <p className="lg:text-base xl:text-lg mb-4">{product.description}</p>
                                <button
                                    onClick={handleBuyClick}
                                    className="py-2 bg-[#976BD6] text-black lg:text-xl xl:text-2xl rounded-md hover:bg-[#684a91] ease-in-out duration-200"
                                >
                                    Купить сейчас ({product.price})
                                </button>
                            </div>

                            {/* Центр: картинка */}
                            <div className="hidden lg:flex justify-center items-center">
                                <img src={product.image} alt={product.name} className={`${product.type === "sub" ? 'lg:w-80 xl:w-86' : 'lg:w-72'}`} />
                            </div>

                            {/* Правая часть: Гарантии */}
                            <div className="flex flex-col lg:w-80 xl:w-96 text-white">
                                <h2 className="text-lg lg:text-xl xl:text-2xl font-bold mb-2 flex justify-center">Нам можно доверять:</h2>
                                <ul className='flex flex-row md:space-x-1 lg:space-x-0 lg:flex-col text-sm lg:text-base xl:text-xl text-center md:text-left'>
                                    <li className='flex flex-row items-center md:space-x-2 lg:border-b lg:py-3 border-r lg:border-r-0'>
                                        <img src={hacker} alt="hacker" className='hidden md:block md:w-10 lg:w-12' />
                                        <span>Никаких входов в ваш игровой аккаунт.
                                            <span> </span>
                                            <span className='underline underline-offset-4 lg:underline-offset-8'>
                                                Мы не запрашиваем игровые
                                                данные.
                                            </span>
                                        </span>
                                    </li>
                                    <li className='flex flex-row items-center md:space-x-2  lg:border-b lg:py-3 border-r lg:border-r-0'>
                                        <img src={block} alt="hacker" className='hidden md:block w-10 lg:w-12' />
                                        <span>
                                            Вам не грозит блокировка
                                            аккаунта в игре! Наш
                                            поставщик официальный.
                                        </span>
                                    </li>
                                    <li className='flex flex-row items-center md:space-x-2 lg:py-3'>
                                        <img src={cashback} alt="hacker" className='hidden md:block w-10 lg:w-12' />
                                        <span>
                                            В случае неполадок сделаем
                                            мгновенный возврат средств
                                        </span>
                                    </li>
                                </ul>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            <Footer />
        </div>
    );
}

export default ProductPage;
