import React, { useState } from 'react';
import { useForm } from 'react-hook-form';
import * as yup from 'yup';
import { yupResolver } from '@hookform/resolvers/yup';
import { toast } from 'react-toastify';
import { FaEye, FaEyeSlash } from 'react-icons/fa'; // Иконки для глаза

// Валидация с использованием yup
const schema = yup.object({
    currentPassword: yup.string().required('Текущий пароль обязателен'),
    newPassword: yup
        .string()
        .min(8, 'Пароль должен содержать минимум 8 символов')
        .matches(/[A-Z]/, 'Пароль должен содержать хотя бы одну заглавную букву')
        .matches(/[a-z]/, 'Пароль должен содержать хотя бы одну строчную букву')
        .matches(/\d/, 'Пароль должен содержать хотя бы одну цифру')
        .matches(/[#?!@$%^&*\-,.]/, 'Пароль должен содержать хотя бы один специальный символ: .#?!@$%^&*-')
        .required('Новый пароль обязателен'),
    confirmPassword: yup
        .string()
        .oneOf([yup.ref('newPassword'), null], 'Пароли не совпадают')
        .required('Подтверждение пароля обязательно'),
}).required();

function ChangePassword() {
    const [loading, setLoading] = useState(false);
    const [showCurrentPassword, setShowCurrentPassword] = useState(false);
    const [showNewPassword, setShowNewPassword] = useState(false);
    const [showConfirmPassword, setShowConfirmPassword] = useState(false);
    const authToken = localStorage.getItem('token');


    const { register, handleSubmit, formState: { errors } } = useForm({
        resolver: yupResolver(schema),
    });

    const onSubmit = async (data) => {
        try {
            setLoading(true);
            const response = await fetch('https://gachashop-backend.onrender.com/user/change-password', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${authToken}`,
                },
                body: JSON.stringify({
                    currentPassword: data.currentPassword,
                    newPassword: data.newPassword,
                }),
            });



            const result = await response.json();
            if (response.ok) {
                toast.success('Пароль успешно изменен!');
            } else {
                toast.error(result.message || 'Ошибка при изменении пароля');
            }
        } catch (error) {
            console.error('Ошибка при изменении пароля:', error);
            toast.error('Произошла ошибка при изменении пароля');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className='lg:max-w-96 w-full'>
            <p className="pt-4 lg:pt-0 text-center lg:text-left font-bold text-2xl lg:text-3xl mb-6 lg:mb-8">Изменить пароль</p>
            <form onSubmit={handleSubmit(onSubmit)} className='flex flex-col items-center lg:items-start'>
                <div className="mb-4 w-full">
                    <label className="block text-white" htmlFor="currentPassword">Введите текущий пароль</label>
                    <div className="relative">
                        <input
                            id="currentPassword"
                            type={showCurrentPassword ? 'text' : 'password'}
                            className="w-full p-2 mt-1 rounded-md text-black"
                            {...register('currentPassword')}
                        />
                        <button
                            type="button"
                            onClick={() => setShowCurrentPassword(!showCurrentPassword)}
                            className="absolute right-2 top-4 text-gray-500"
                        >
                            {showCurrentPassword ? <FaEyeSlash /> : <FaEye />}
                        </button>
                    </div>
                    {errors.currentPassword && <span className="text-red-500">{errors.currentPassword.message}</span>}
                </div>

                <div className="mb-4 w-full">
                    <label className="block text-white" htmlFor="newPassword">Введите новый пароль</label>
                    <div className="relative">
                        <input
                            id="newPassword"
                            type={showNewPassword ? 'text' : 'password'}
                            className="w-full p-2 mt-1 rounded-md text-black"
                            {...register('newPassword')}
                        />
                        <button
                            type="button"
                            onClick={() => setShowNewPassword(!showNewPassword)}
                            className="absolute right-2 top-4 text-gray-500"
                        >
                            {showNewPassword ? <FaEyeSlash /> : <FaEye />}
                        </button>
                    </div>
                    {errors.newPassword && <span className="text-red-500">{errors.newPassword.message}</span>}
                </div>

                <div className="mb-4 w-full">
                    <label className="block text-white" htmlFor="confirmPassword">Повторите новый пароль</label>
                    <div className="relative">
                        <input
                            id="confirmPassword"
                            type={showConfirmPassword ? 'text' : 'password'}
                            className="w-full p-2 mt-1 rounded-md text-black"
                            {...register('confirmPassword')}
                        />
                        <button
                            type="button"
                            onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                            className="absolute right-2 top-4 text-gray-500"
                        >
                            {showConfirmPassword ? <FaEyeSlash /> : <FaEye />}
                        </button>
                    </div>
                    {errors.confirmPassword && <span className="text-red-500">{errors.confirmPassword.message}</span>}
                </div>

                <div className="mt-4">
                    <button
                        type="submit"
                        className={`py-2 px-4 rounded-md ${loading ? 'bg-gray-400' : 'bg-black border-2 rounded-full border-[#976BD6] hover:bg-[#976BD6] hover:text-black ease-in-out duration-150'}`}
                        disabled={loading}
                    >
                        {loading ? 'Загрузка...' : 'Сохранить изменения'}
                    </button>
                </div>
            </form>
        </div>
    );
}

export default ChangePassword;
