import Header from "../components/Header";
import Footer from "../components/Footer";
import Breadcrumbs from "../components/Breadcrumbs";
import { Link, useLocation } from 'react-router-dom';
import React, { useState, useEffect } from 'react';

function Catalog() {
    const [gamesData, setGamesData] = useState(null);
    const [categories, setCategories] = useState([]);
    const [products, setProducts] = useState([]);
    const [gameColors, setGameColors] = useState({});
    const [selectedGame, setSelectedGame] = useState(null);
    const [selectedProductType, setSelectedProductType] = useState(null);
    const [selectedQuantity, setSelectedQuantity] = useState(null);
    const [selectedDays, setSelectedDays] = useState(null);
    const [filtersApplied, setFiltersApplied] = useState(false);
    const location = useLocation();
    const gameId = location.state?.gameId;

    const crumbs = [
        { label: 'Главная', path: '/' },
        { label: 'Выбор игры', path: '/gamechoose' },
        { label: 'Каталог', path: '/catalog' }
    ];

    useEffect(() => {
        const savedFilters = JSON.parse(localStorage.getItem('catalogFilters'));
        if (savedFilters) {
            setSelectedGame(savedFilters.selectedGame);
            setSelectedProductType(savedFilters.selectedProductType);
            setSelectedQuantity(savedFilters.selectedQuantity);
            setSelectedDays(savedFilters.selectedDays);
        }

        const fetchCatalog = async () => {
            try {
                const gamesData = await fetch('https://gachashop-backend.onrender.com/games').then(res => res.json());
                const productsData = await fetch('https://gachashop-backend.onrender.com/catalog').then(res => res.json());
                const categoriesData = await fetch('https://gachashop-backend.onrender.com/categories').then(res => res.json());

                const gameColors = gamesData.reduce((acc, game) => {
                    acc[game.id] = game.id === 1 ? 'text-[#55CDCC]' : game.id === 2 ? 'text-[#3b7ece]' : 'text-[#2e2d39]';
                    return acc;
                }, {});

                setGameColors(gameColors);
                setGamesData(gamesData);
                setProducts(productsData);
                setCategories(categoriesData);
            }
            catch (error) {
                console.error('Ошибка при загрузке данных:', error);
            }
        };
        fetchCatalog();

        if (gameId) {
            setSelectedGame(parseInt(gameId));
        }
    }, [gameId]);

    useEffect(() => {
        const filters = {
            selectedGame,
            selectedProductType,
            selectedQuantity,
            selectedDays,
        };
        localStorage.setItem('catalogFilters', JSON.stringify(filters));
    }, [selectedGame, selectedProductType, selectedQuantity, selectedDays]);

    const filteredProducts = () => {
        let filtered = [...products];

        if (selectedGame) {
            filtered = filtered.filter(product => product.game_id === parseInt(selectedGame));
        }
        if (selectedProductType) {
            filtered = filtered.filter(product => product.type === selectedProductType);
        }
        if (selectedQuantity) {
            filtered = filtered.filter(product => product.quantity === selectedQuantity);
        }
        if (selectedDays !== null) {
            filtered = filtered.filter(product => product.days === parseInt(selectedDays));
        }
        return filtered;
    };

    const handleResetFilters = () => {
        setSelectedGame(null);
        setSelectedProductType(null);
        setSelectedQuantity(null);
        setSelectedDays(null);
        setFiltersApplied(false);
    };

    const productsToDisplay = filteredProducts();
    const productsByGame = gamesData ? gamesData.reduce((acc, game) => {
        acc[game.id] = productsToDisplay.filter(product => product.game_id === game.id);
        return acc;
    }, {}) : {};

    const quantityOptions = [...new Set(categories.filter(item => item.catname === 'Количество игровой валюты').map(item => item.optname))];
    const daysOptions = [...new Set(categories.filter(item => item.catname === 'Количество дней').map(item => parseInt(item.optname.split(' ')[0])))]

    return (
        <div className="bg-[#000000] font-seravek min-h-screen flex flex-col">
            <div className="w-full">
                <Header />
                <div className="container mx-auto px-6 md:px-11 mt-2">
                    <Breadcrumbs crumbs={crumbs} />
                </div>
            </div>

            <div className="flex flex-col flex-grow">
                <div className="container flex-grow mx-auto">

                    <div className="flex flex-col lg:flex-row mt-5 justify-center lg:justify-normal items-center lg:items-start">
                        <div className="flex flex-col w-full lg:w-[227px] h-full bg-[#4E2982] lg:mr-[80px] mb-4 lg:mb-0 rounded-b-xl lg:rounded-b-none lg:rounded-r-xl lg:rounded-br-xl">

                            {/* Фильтр "Игра" */}
                            <div className="flex flex-row lg:flex-col justify-center m-[6px] lg:w-[200px] flex-shrink-0">
                                <div className="hidden lg:block pl-[10px] pt-[5px] mb-[5px]">
                                    <h3 className="font-bold text-[15px] text-[#FFFFFF]">Игра</h3>
                                </div>
                                {gamesData?.map((game) => (
                                    <button
                                        key={game.id}
                                        onClick={() => {
                                            setSelectedGame(game.id);
                                            setSelectedProductType(null);
                                            setSelectedQuantity(null);
                                            setSelectedDays(null);
                                            setFiltersApplied(false);
                                        }}
                                        className={`m-[4px] px-[10px] py-[5px] text-[15px] rounded-md text-white text-center md:text-left ${selectedGame === game.id ? 'border-2 border-[#976BD6] bg-[#6A4BAF]' : 'bg-[#6A4BAF]'
                                            } hover:bg-[#7D5FD0]`}
                                    >
                                        {game.name}
                                    </button>
                                ))}
                            </div>

                            {/* Фильтр "Тип товара" */}
                            <div className="flex flex-row justify-center lg:justify-normal lg:flex-col m-[6px] lg:w-[200px] flex-shrink-0">
                                <div className="pl-[10px] pt-[5px] mb-[5px]">
                                    <h3 className="font-bold hidden lg:block text-[15px] text-[#FFFFFF]">Тип товара</h3>
                                </div>
                                {["pack", "sub"].map((type) => (
                                    <button
                                        key={type}
                                        onClick={() => {
                                            setSelectedProductType(type);
                                            setSelectedQuantity(null);
                                            setSelectedDays(null);
                                            setFiltersApplied(false);
                                        }}
                                        className={`m-[4px] px-[10px] py-[5px] text-[15px] rounded-md text-white text-left ${selectedProductType === type ? 'border-2 border-[#976BD6] bg-[#6A4BAF]' : 'bg-[#6A4BAF]'
                                            } hover:bg-[#7D5FD0]`}
                                    >
                                        {type === "pack" ? "Ограниченный пак" : "Подписка"}
                                    </button>
                                ))}
                            </div>

                            {/* Фильтр "Количество игровой валюты" */}
                            {selectedProductType === "pack" && (
                                <div className="flex flex-row lg:flex-col justify-center lg:justify-normal m-[6px] lg:w-[200px] flex-shrink-0">
                                    <div className="pl-[10px] pt-[5px] mb-[5px]">
                                        <h3 className="font-bold hidden lg:block text-[15px] text-[#FFFFFF]">Количество игровой валюты</h3>
                                    </div>
                                    {quantityOptions.map((option) => (
                                        <button
                                            key={option}
                                            onClick={() => setSelectedQuantity(option)}
                                            disabled={filtersApplied}
                                            className={`m-[4px] px-[10px] py-[5px] text-[15px] rounded-md text-white text-left ${selectedQuantity === option ? 'border-2 border-[#976BD6] bg-[#6A4BAF]' : 'bg-[#6A4BAF]'
                                                } hover:bg-[#7D5FD0] disabled:opacity-50`}
                                        >
                                            {option}
                                        </button>
                                    ))}
                                </div>
                            )}

                            {/* Фильтр "Количество дней" */}
                            {selectedProductType === "sub" && (
                                <div className="flex flex-row lg:flex-col justify-center lg:justify-normal m-[6px] lg:w-[200px] flex-shrink-0">
                                    <div className="pl-[10px] pt-[5px] mb-[5px]">
                                        <h3 className="font-bold hidden lg:block text-[15px] text-[#FFFFFF]">Количество дней</h3>
                                    </div>
                                    {daysOptions.map((option) => (
                                        <button
                                            key={option}
                                            onClick={() => setSelectedDays(option)}
                                            disabled={filtersApplied}
                                            className={`text-center m-[4px] px-[10px] py-[5px] text-[15px] rounded-md text-white lg:text-left ${parseInt(selectedDays) === option ? 'border-2 border-[#976BD6] bg-[#6A4BAF]' : 'bg-[#6A4BAF]'
                                                } hover:bg-[#7D5FD0] disabled:opacity-50`}
                                        >
                                            {option} дней
                                        </button>
                                    ))}
                                </div>
                            )}

                            <button onClick={handleResetFilters} className="mt-4 px-4 py-2 bg-[#976BD6] text-white hover:bg-[#7550A9] flex-shrink-0 rounded-b-xl lg:rounded-b-none lg:rounded-br-xl">Сбросить фильтры</button>
                        </div>


                        <div className="mb-4">
                            {gamesData && Object.entries(productsByGame)
                                .filter(([gameId, gameProducts]) => gameProducts.length > 0)
                                .map(([gameId, gameProducts]) => (
                                    <div key={gameId}>

                                        <p className="flex justify-center lg:block lg:justify-normal text-lg lg:text-xl xl:text-2xl font-bold mb-4 text-[#FFFFFF] uppercase">
                                            {gamesData.find(game => game.id === parseInt(gameId))?.name}
                                        </p>

                                        <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-2 md:gap-4 xl:gap-6 mb-10">
                                            {gameProducts.map((product) => (
                                                <div className="flex flex-col items-center justify-start bg-[#FFFFFF] lg:w-48 xl:w-56 md:h-[340px] rounded-lg" id={product.type}>

                                                    <div className='flex flex-col items-center justify-center md:h-[175px]'>

                                                        <img src={product.image}
                                                            className={`${product.type === "pack" ? 'h-16 md:h-[100px]' : 'h-24 md:h-[175px]'}`}
                                                            alt={product.name} />

                                                        {product.type === "pack" &&
                                                            <p className={`text-base ${gameColors[gameId]}`}>{product.quantity}</p>}

                                                    </div>

                                                    <div className="flex flex-col items-center">

                                                        <div className="mb-[10px]">

                                                            <p className="md:w-[170px] text-center text-sm md:text-base px-1 text-[#000000]">{product.name}</p>

                                                        </div>

                                                        <div className="bg-[#976BD6] rounded-lg w-[70px] text-center mb-2 md:mb-5">

                                                            <p className="text-[#FFFFFF] text-sm md:text-base">{product.price}</p>

                                                        </div>

                                                        <Link to={`/product/${product.id}`} className="text-[#4E2982] text-sm md:text-base hover:underline underline-offset-4">Подробнее . . .</Link>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                ))}
                        </div>
                    </div>
                </div>
            </div>
            <Footer />
        </div>
    )

}

export default Catalog;