import logo from "../logo.png";
import { Link, useLocation } from 'react-router-dom';
import { useUserContext } from '../components/Context';
import { useState } from 'react';
import { Menu, X } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

function Header() {
    const { user } = useUserContext();
    const location = useLocation();
    const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

    const navLinks = [
        { path: "/", name: "Главная" },
        { path: "/catalog", name: "Каталог" },
        { path: "/reviews", name: "Отзывы" },
        { path: "/faq", name: "FAQ" },
        { path: "/support", name: "Поддержка" },
    ];

    return (
        <div className="w-full">
            <div className="container h-[78px] mx-auto flex items-center justify-between px-4">
                <div className="md:ml-5 ease-in-out duration-200 hover:scale-110">
                    <Link to="/" className="w-full">
                        <img src={logo} className="w-16" alt="logo" />
                    </Link>
                </div>

                {/* Desktop menu */}
                <div className="hidden lg:flex">
                    <ul className="text-[#FFFFFF] text-[16px] flex flex-row underline-offset-8 space-x-[10px]">
                        {navLinks.map(({ path, name }) => (
                            <li key={path} className={location.pathname !== path ? 'hover:text-[#976BD6] ease-in-out duration-100 hover:scale-110' : ''}>
                                <Link to={path} className={location.pathname === path ? 'underline text-[#976BD6]' : ''}>
                                    {name}
                                </Link>
                            </li>
                        ))}
                    </ul>
                </div>

                {/* Mobile burger icon */}
                <div className="lg:hidden">
                    <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} className="text-white focus:outline-none">
                        {isMobileMenuOpen ? <X size={28} /> : <Menu size={28} />}
                    </button>
                </div>

                {/* User avatar / auth */}
                <div>
                    {user ? (
                        <Link to="/settings/personal-info">
                            <div className="w-11 rounded-full overflow-hidden border-2 border-[#976BD6] flex items-center justify-center">
                                <img src={user.avatar_url} alt="Avatar" className="w-full h-full" />
                            </div>
                        </Link>
                    ) : (
                        <Link to="/auth" className="text-[#976BD6]">
                            <span className="px-3 py-1 border border-[#976BD6] text-base hover:bg-[#976BD6] hover:text-[#000000] ease-in-out duration-200 rounded">Регистрация</span>
                        </Link>
                    )}
                </div>
            </div>

            {/* Mobile menu dropdown */}
            <AnimatePresence>
                {isMobileMenuOpen && (
                    <motion.div
                        initial={{ opacity: 0, scale: 0.95 }}
                        animate={{ opacity: 1, scale: 1 }}
                        exit={{ opacity: 0, scale: 0.95 }}
                        transition={{ duration: 0.3 }}
                        className="lg:hidden fixed top-0 left-0 z-50 w-full h-screen bg-[#1e1e1e] flex flex-col items-center justify-center px-4 py-4"
                    >
                        {/* Кнопка закрытия */}
                        <button
                            onClick={() => setIsMobileMenuOpen(false)}
                            className="absolute top-4 right-4 text-white"
                        >
                            <X size={32} />
                        </button>

                        <ul className="text-[#FFFFFF] text-[20px] flex flex-col space-y-6 text-center">
                            {navLinks.map(({ path, name }) => (
                                <li key={path}>
                                    <Link
                                        to={path}
                                        className={`block ${location.pathname === path ? 'underline text-[#976BD6]' : 'hover:text-[#976BD6]'}`}
                                        onClick={() => setIsMobileMenuOpen(false)}
                                    >
                                        {name}
                                    </Link>
                                </li>
                            ))}
                        </ul>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
}

export default Header;
