import { useState, useEffect } from 'react';
import { useLocation, useNavigate, Link } from 'react-router-dom';
import Header from "../components/Header";
import Footer from "../components/Footer";
import back from "../components/images/Register_and_Auth/back-button.png";
import { useUserContext } from "../components/Context";
import { toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

function UserReview() {
    const navigate = useNavigate();
    const [rating, setRating] = useState(0);
    const [reviewText, setReviewText] = useState('');
    const [orderId, setOrderId] = useState(null);
    const [isAgreed, setIsAgreed] = useState(false);

    const { user } = useUserContext();

    const location = useLocation();
    const params = new URLSearchParams(location.search);
    const orderCode = params.get('code');
    const token = localStorage.getItem('token');

    useEffect(() => {
        if (!user) {
            navigate('/');
            return;
        }
        if (!orderCode) {
            navigate('/catalog');
            return;
        }
    }, [user, orderCode, navigate]);

    const handleRatingChange = (newRating) => {
        setRating(newRating);
    };

    useEffect(() => {
        const fetchOrderId = async () => {
            try {
                const token = localStorage.getItem('token');

                const response = await fetch(`https://gachashop-backend.onrender.com/order/get-order-id-by-code?orderCode=${orderCode}`, {
                    headers: {
                        'Authorization': `Bearer ${token}`,
                    },
                });
                const data = await response.json();

                if (data.status === 'success') {
                    setOrderId(data.order_id);
                } else {
                    toast.error('Не удалось найти заказ.');
                }
            } catch (err) {
                toast.error('Ошибка сети. Попробуйте снова.');
            }
        };

        if (orderCode) {
            fetchOrderId();
        }
    }, [orderCode]);

    const Star = ({ filled }) => (
        <svg
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 24 24"
            fill={filled ? '#976BD6' : 'none'}
            stroke="#976BD6"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
            className="w-8 h-8 cursor-pointer"
        >
            <polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2" />
        </svg>
    );

    const handleSubmit = async (e) => {
        e.preventDefault();

        if (rating === 0) {
            toast.error('Пожалуйста, поставьте оценку.');
            return;
        }

        if (!orderId) {
            toast.error('Не удалось определить заказ.');
            return;
        }

        if (!isAgreed) {  // Проверка на согласие с публикацией
            toast.error('Вы должны согласиться с условиями публикации отзыва.');
            return;
        }

        try {
            const checkResponse = await fetch(`https://gachashop-backend.onrender.com/user-review/check?user_id=${user.id}&order_id=${orderId}`);
            const checkData = await checkResponse.json();

            if (checkData.status === 'exists') {
                toast.error('Вы уже оставляли отзыв для этого заказа.');
                return;
            }

            // Если отзыва нет, отправляем новый отзыв
            const reviewData = {
                user_id: user.id,
                review: rating,
                text: reviewText,
                order_id: orderId,
            };

            const response = await fetch('https://gachashop-backend.onrender.com/user-review/create', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${token}`,
                },
                body: JSON.stringify(reviewData)
            });

            if (response.ok) {
                navigate('/');
                toast.success('Отзыв успешно опубликован!');
            } else {
                toast.error('Ошибка при отправке отзыва. Попробуйте снова.');
            }

        } catch (err) {
            toast.error('Ошибка сети. Попробуйте снова.');
        }
    };

    return (
        <div className="bg-[#000000] font-seravek min-h-screen flex flex-col">
            <div className='w-full'>
                <Header />
                {/* Кнопка назад */}
                <div className="container mx-auto px-6 md:px-11 mt-[30px]">
                    <Link to="/catalog" className="flex items-center space-x-[10px]">
                        <img src={back} alt="Стрелка назад" className="w-4 xl:w-6" />
                        <span className="text-lg xl:text-xl text-[#FFFFFF]">Вернуться в магазин</span>
                    </Link>
                </div>
            </div>
            <div className="flex flex-col flex-grow">
                <div className="container flex flex-col flex-grow justify-center items-center mx-auto px-2 lg:px-0">
                    <div className='text-white flex flex-col text-xl lg:w-[700px]'>
                        <p className='pb-1 font-bold text-2xl lg:text-3xl'>Оставить отзыв о заказе</p>

                        <form onSubmit={handleSubmit} className="flex flex-col items-center">
                            <div className='w-full'>
                                <div className="flex space-x-1 mb-[20px]">
                                    {[1, 2, 3, 4, 5].map((star) => (
                                        <div key={star} onClick={() => handleRatingChange(star)}>
                                            <Star filled={star <= rating} />
                                        </div >
                                    ))}
                                </div>

                                <textarea
                                    className="w-full h-[200px] p-[10px] bg-transparent border-[#976BD6] rounded-xl text-white focus:outline-0 focus:border-[#976BD6] focus:ring-0"
                                    placeholder="Напишите ваш отзыв... (необязательно)"
                                    value={reviewText}
                                    onChange={(e) => setReviewText(e.target.value)}
                                />

                                <div className="mb-4">
                                    <input
                                        type="checkbox"
                                        id="agree"
                                        checked={isAgreed}
                                        onChange={() => setIsAgreed(!isAgreed)}
                                        className="text-[#976BD6] mr-2 focus:ring-0 focus:ring-offset-0 cursor-pointer"
                                    />
                                    <label htmlFor="agree" className="text-white text-base lg:text-lg">Я согласен, что мой отзыв будет опубликован на сайте</label>
                                </div>
                            </div>


                            <button
                                type="submit"
                                className="px-4 lg:px-8 py-1 lg:py-2 rounded-md justify-center items-center text-center text-black text-lg lg:text-xl bg-[#976BD6] hover:bg-[#684a91] ease-in-out duration-200"
                            >
                                Опубликовать отзыв
                            </button>
                        </form>
                    </div>
                </div>
            </div>
            <Footer />
        </div>
    );
}

export default UserReview;