// theme.js
import { createTheme } from '@mui/material/styles';

const theme = createTheme({
  breakpoints: {
    values: {
      xs: 0,
      sm: 360,
      md: 600,
      lg: 1024,
      xl: 1366,
      '2xl': 1920,  // Необязательно, это зависит от твоих нужд
    },
  },
});

export default theme;